    "API personalizada HTTP {0}": "{0} Custom HTTP API",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Open the dedicated SR session in Chrome/Edge and log in to YouTube if necessary. The session is automatically reused and synchronized. No need to search for cookies or cache in folders. YouTube restrictions may require re-authentication or prevent some tracks.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Open the Spotify Developer Dashboard and log in with your account. Applications in Development Mode require Premium from the owner and authorized users in the panel.",
