    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "Add URL as Browser Source in OBS. Keep Kaia Chat open, even with the window hidden.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "Add the widget URLs used in OBS: Streamlabs, StreamElements or a custom service. Each source has its own name/platform. Widgets are muted; recognized text is read only through the Reader output. Alert sources can announce events even when normal chat reading is disabled.",
    "Aguardando pedido !sr": "Waiting for !sr order",
    "Alertas": "Alerts",
    "Alertas para o streamer": "Alerts for the streamer",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "Some temporary audio is in use. Cleaning will be repeated at the next opening.",
    "Alguém": "Someone",
    "Alt": "Alt",
    "Alta prioridade": "High priority",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "High priority reads all messages and moves to the front of the queue after finishing the current speech. Normal and low priority have separate counts. To follow the live, old messages are discarded according to the maximum delay, including priority ones. In a full queue, the oldest ones with the lowest priority leave first. The break counts from the beginning of the preparation, without adding a pause after each speech. History retrieved on connect is not spoken.",
