    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify publishes the track to HUDs; playback continues in the Spotify app. Authorization and tokens are automatically renewed. SR plays requests from YouTube, does not download audio from Spotify.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "The backup includes messages received from all platforms, including nicknames hidden by blocked Chats. The fade only clears the screen.",
