    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "Audio privacy: SR songs are transmitted without permanent download. Speeches use temporary files, deleted after use and when closing. Remnants of an interrupt are cleaned up at the next audio engine startup. Sounds chosen by you and the TXT backup are preserved.",
