    "Salve e ative a fonte antes de abrir a prévia.": "Save and activate the source before opening the preview.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "Save using the SR Save button. Requests are next to play after the current track, before the songs in the playlist. The limits apply to new entries and do not remove songs already accepted. Chat sounds and prompts use Reader output; music uses the SR output. OBS should only capture SR output/process to keep warnings private.",
