    "; tentando novamente…": "; intentando de nuevo...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"activos/banderas/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat — sesión {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "La API debe proporcionar una identificación única para cada mensaje.",
    "A API retornou uma resposta muito grande.": "La API devolvió una respuesta muy grande.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "El puerto 19348 está ocupado. Cierre otra autorización de Spotify y vuelva a intentarlo.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "La vista previa utiliza música real. Sólo Guardar aplica los cambios a la fuente OBS.",
    "A sessão YouTube demorou para responder.": "La sesión de YouTube tardó en responder.",
    "API personalizada HTTP {0}": "API HTTP personalizada de {0}",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Abra la sesión SR dedicada en Chrome/Edge e inicie sesión en YouTube si es necesario. La sesión se reutiliza y sincroniza automáticamente. No es necesario buscar cookies ni caché en carpetas. Las restricciones de YouTube pueden requerir una nueva autenticación o impedir algunas pistas.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Abra el Panel de desarrollador de Spotify e inicie sesión con su cuenta. Las aplicaciones en modo de desarrollo requieren Premium del propietario y de los usuarios autorizados en el panel.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "Abre el reproductor con su propio nombre: kaia_sr.exe o kaia_voz.exe.",
    "Abrir HUD original": "Abrir HUD original",
    "Abrir HUD padrão": "Abrir HUD predeterminado",
    "Abrir HUD personalizado": "Abrir HUD personalizado",
    "Abrir configurações / liberar cliques": "Abrir configuración/liberar clics",
