    "Abrir pop-up": "Abrir ventana emergente",
    "Abrir prévia desta fonte": "Abrir vista previa de esta fuente",
    "Aceitar pedidos !sr das lives": "Aceptar solicitudes de !sr de vidas",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "Encuentra el video más cercano al nombre. Enlace = usa la identificación. Nombre = búsqueda ytsearch.",
    "Adicionar faixa à playlist de fundo": "Agregar pista a la lista de reproducción de fondo",
    "Adicionar pedido SR": "Agregar orden SR",
    "Adicionar playlist": "Agregar lista de reproducción",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "Agregue una URL como fuente de navegador en OBS. Mantenga abierto Kaia Chat, incluso con la ventana oculta.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "Agregar URL de widget usados ​​sin OBS. Streamlabs, StreamElements o servicio personalizado. Cada fuente tiene su propio nombre/plataforma. Los widgets están silenciados; o texto reconhecido é lido somente na saída do Leitor. Habilitar fuentes de alerta también habilita advertencias con la lectura normal desactivada.",
    "Aguardando pedido !sr": "Esperando pedido de !sr",
    "Alertas": "Alertas",
    "Alertas para o streamer": "Alertas para el streamer",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "Algunos audios temporales están en uso. La limpieza se repetirá en la próxima apertura.",
    "Alguém": "Alguien",
    "Alt": "Alt.",
    "Alta prioridade": "Alta prioridad",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "Alta prioridad lê todos los mensajes y passa à frente da fila, después de terminar a fala actual. Prioridad normal y baja de los contaminantes separados. Para acompañar un directo, los mensajes antigas se descartan conforme o traso máximo, inclusive como prioritarias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde el inicio de la preparación, sem acrecentar una pausa después de cada fala. Histórico recuperado ao conectar não é falado.",
