    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "OBS → agregar fuente del navegador. Utilice inicialmente 800 × 320 y recorte según el diseño. Fondo transparente; No es necesaria la clave de croma.",
