    "Preparando/reproduzindo aviso": "Aviso de preparación/reproducción",
    "Preservar as cores dos nomes de usuário": "Preservar los colores del nombre de usuario",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "Privacidad de audio: las canciones SR se transmiten sin descarga permanente. Los discursos utilizan archivos temporales, que se eliminan después de su uso y al cerrarlos. Los restos de una interrupción se limpian en el siguiente inicio del motor de audio. Se conservan los sonidos elegidos por usted y la copia de seguridad TXT.",
