    "Salve e ative a fonte antes de abrir a prévia.": "Guarde y active la fuente antes de abrir la vista previa.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "Guarde usando el botón SR Save. Las solicitudes se reproducen después de la pista actual, antes de las canciones de la lista de reproducción. Los límites se aplican a nuevas entradas y no eliminan canciones ya aceptadas. Los sonidos y las indicaciones del chat utilizan la salida del Reader; la música utiliza la salida SR. OBS solo debe capturar la salida/proceso SR para mantener las advertencias privadas.",
