    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "Salidas de audio actualizadas. Seleccione la salida de lectura.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "Salidas de audio únicas. SR y Kaia utilizan dispositivos diferentes. No utilice ffmpeg -f wasapi (muchas versiones de Windows no tienen este muxer). Predeterminado = ffplay. Dispositivo elegido = ffmpeg PCM + dispositivo de sonido.",
