    ": texto do widget incorporado encontrado; aguardando alerta e término da mídia.": ": texte du widget intégré trouvé ; en attente d'alerte et de fin de média.",
    "; tentando novamente…": "; j'essaye à nouveau...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"actifs/flags/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat — session {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "L'API doit fournir un identifiant unique pour chaque message.",
    "A API retornou uma resposta muito grande.": "L'API a renvoyé une réponse très volumineuse.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "Le port 19348 est occupé. Fermez une autre autorisation Spotify et réessayez.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "L'aperçu utilise la vraie musique. Seul Enregistrer applique les modifications à la source OBS.",
    "A sessão YouTube demorou para responder.": "La session YouTube était lente à répondre.",
    "API personalizada HTTP {0}": "API HTTP personnalisée {0}",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Ouvrez la session SR dédiée dans Chrome/Edge et connectez-vous à YouTube si nécessaire. La session est automatiquement réutilisée et synchronisée. Pas besoin de rechercher des cookies ou du cache dans les dossiers. Les restrictions YouTube peuvent nécessiter une ré-authentification ou empêcher certaines pistes.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Ouvrez le tableau de bord du développeur Spotify et connectez-vous avec votre compte. Les applications en mode développement nécessitent Premium de la part du propriétaire et des utilisateurs autorisés dans le panneau.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "Ouvre le lecteur avec son propre nom : kaia_sr.exe ou kaia_voz.exe.",
    "Abrir HUD original": "Ouvrir le HUD d'origine",
    "Abrir HUD padrão": "Ouvrir le HUD par défaut",
    "Abrir HUD personalizado": "Ouvrir le HUD personnalisé",
    "Abrir configurações / liberar cliques": "Ouvrir les paramètres / Libérer les clics",
    "Abrir overlay": "Ouvrir la superposition",
    "Abrir painel Spotify": "Ouvrir le panneau Spotify",
    "Abrir pop-up": "Ouvrir la fenêtre contextuelle",
    "Abrir prévia desta fonte": "Ouvrir l'aperçu de cette police",
    "Aceitar pedidos !sr das lives": "Accepter les requêtes !sr des vies",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "Recherche la vidéo la plus proche du nom. Link = utilise l'identifiant. Nom = recherche ytsearch.",
    "Adicionar faixa à playlist de fundo": "Ajouter une piste à la liste de lecture en arrière-plan",
    "Adicionar pedido SR": "Ajouter une commande SR",
    "Adicionar playlist": "Ajouter une liste de lecture",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "Ajoutez une URL comme source du navigateur dans OBS. Gardez Kaia Chat ouvert, même avec la fenêtre cachée.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "Ajoutez les URL de widgets utilisées dans OBS. Streamlabs, StreamElements ou service personnalisé. Chaque police a son propre nom/plateforme. Les widgets sont désactivés ; le texte reconnu est lu uniquement à la sortie du Reader. L'activation des sources d'alerte active également les avertissements avec la lecture normale désactivée.",
    "Aguardando pedido !sr": "En attente de la commande !sr",
    "Alertas": "Alertes",
    "Alertas para o streamer": "Alertes pour le streamer",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "Certains fichiers audio temporaires sont en cours d'utilisation. Le nettoyage sera répété à la prochaine ouverture.",
    "Alguém": "Quelqu'un",
    "Alt": "Alt",
    "Alta prioridade": "Haute priorité",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "La priorité élevée lit tous les messages et se place au début de la file d'attente après avoir terminé le discours en cours. Les priorités normales et faibles ont des comptes distincts. Pour suivre le direct, les anciens messages sont écartés selon le délai maximum, y compris les prioritaires. Dans une file d'attente pleine, les plus anciens et avec la priorité la plus basse partent en premier. La pause compte dès le début de la préparation, sans ajouter de pause après chaque intervention. L'historique récupéré lors de la connexion n'est pas prononcé.",
