    "Nas configurações da aplicação, copie o Client ID para o campo desta aba. O fluxo PKCE de aplicativo desktop dispensa Client Secret; o campo opcional permite guardar o seu, se utilizado.": "Dans les paramètres de l'application, copiez l'ID client dans le champ de cet onglet. Le flux PKCE de l’application de bureau ne nécessite pas de clé secrète client ; le champ facultatif vous permet de sauvegarder le vôtre, s'il est utilisé.",
