    "Não li a playlist: {0}": "Je n'ai pas lu la playlist : {0}",
    "O SR está no mudo, independentemente do volume salvo.": "SR est mis en sourdine quel que soit le volume enregistré.",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify publie la piste sur les HUD ; la lecture continue dans l'application Spotify. L'autorisation et les jetons sont automatiquement renouvelés. SR lit les requêtes de YouTube, ne télécharge pas l'audio de Spotify.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "La sauvegarde inclut les messages reçus de toutes les plateformes, y compris les surnoms masqués par les chats bloqués. Le fondu efface uniquement l'écran.",
    "O campo da lista de mensagens não contém um array JSON.": "Le champ de la liste des messages ne contient pas de tableau JSON.",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "La commande {0} a pris trop de temps. Les autres champs restent disponibles ; essayer à nouveau.",
    "O decodificador não produziu áudio.": "Le décodeur n'a pas produit de son.",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "Le compteur utilise l'audio de la sortie sélectionnée. D'autres sons sur le même appareil peuvent également apparaître. L'éditeur conserve les thèmes, CSS, RVB et barres du package d'origine.",
    "O motor de áudio demorou para iniciar.": "Le moteur audio mettait du temps à démarrer.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "Le navigateur n'a pas libéré la session dédiée. Fermez cette fenêtre YouTube et essayez à nouveau de vous connecter.",
    "O navegador recusou a sincronização da sessão.": "Le navigateur a refusé de synchroniser la session.",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "La deuxième superposition affiche les mêmes données que SR/Spotify. Modifiez l'apparence ici ; le HUD standard reste disponible.",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "OBS → ajouter une police de navigateur. Utilisez initialement 800 × 320 et recadrez en fonction de la mise en page. Fond transparent ; Pas besoin d'incrustation chroma.",
    "Oculte mensagens e sons de nicks específicos": "Masquer les messages et les sons de pseudos spécifiques",
