    "Preparando voz de {0} · {1} na fila · {2} descartadas pelo limite/filtro": "Préparation de {0} · Voix {1} en file d'attente · {2} rejeté par limite/filtre",
    "Preparando/reproduzindo aviso": "Préparation/lecture d'une notice",
    "Preservar as cores dos nomes de usuário": "Conserver les couleurs du nom d'utilisateur",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "Confidentialité audio : les chansons SR sont transmises sans téléchargement permanent. Les discours utilisent des fichiers temporaires, supprimés après utilisation et à la fermeture. Les restes d'une interruption sont nettoyés au prochain démarrage du moteur audio. Les sons choisis par vous et la sauvegarde TXT sont conservés.",
    "Proteção de credenciais indisponível neste Windows.": "Protection des informations d'identification indisponible sur ce Windows.",
