    "Salvar widget e atualizar prévia": "Enregistrer le widget et mettre à jour l'aperçu",
    "Salve e ative a fonte antes de abrir a prévia.": "Enregistrez et activez la source avant d'ouvrir l'aperçu.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "Enregistrez à l'aide du bouton SR Save. Les demandes sont ensuite lues après la piste en cours, avant les chansons de la liste de lecture. Les limites s'appliquent aux nouvelles entrées et ne suppriment pas les chansons déjà acceptées. Les sons et les invites de discussion utilisent la sortie Reader ; la musique utilise la sortie SR. OBS ne doit capturer que la sortie/le processus SR pour garder les avertissements privés.",
    "Salve seu Client ID primeiro.": "Enregistrez d'abord votre identifiant client.",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "Enregistré. La superposition OBS se met à jour dans les deux secondes.",
