    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "Sorties audio mises à jour. Sélectionnez la sortie de lecture.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "Sorties audio uniques. SR et Kaia utilisent des appareils différents. N'utilisez pas ffmpeg -f wasapi (de nombreuses versions de Windows n'ont pas ce multiplexeur). Par défaut = ffplay. Appareil choisi = ffmpeg PCM + sounddevice.",
