    "Tom de teste enviado à saída do SR. Confirme se você ouviu; este teste não usa YouTube nem os alertas.": "Tonalité de test envoyée à la sortie SR. Confirmez que vous avez entendu ; Ce test n'utilise pas YouTube ni les alertes.",
