    "Use um endpoint JSON público. Links de live e widgets HTML não são lidos automaticamente; cada serviço precisa permitir acesso às mensagens.": "Utilisez un point de terminaison JSON public. Les liens dynamiques et les widgets HTML ne sont pas lus automatiquement ; chaque service doit permettre l'accès aux messages.",
