    "YouTube exige login para este acesso. Na aba SR, clique Conectar YouTube, faça login na sessão dedicada e depois Testar acesso.": "YouTube nécessite une connexion pour cet accès. Dans l'onglet SR, cliquez sur Connecter YouTube, connectez-vous à la session dédiée puis Testez l'accès.",
