    ": alerta identificado; aguardando o fim para falar.": ": Warnung identifiziert; Ich warte darauf, dass das Ende spricht.",
    ": falha ao carregar. Verifique o URL do widget.": ": Laden fehlgeschlagen. Überprüfen Sie die Widget-URL.",
