    ": seletor CSS inválido. Corrija o campo do texto do alerta.": ": Ungültiger CSS-Selektor. Korrigieren Sie das Textfeld für die Warnung.",
    ": texto do widget incorporado encontrado; aguardando alerta e término da mídia.": ": Eingebetteter Widget-Text gefunden; Warten auf Alarm und Medienende.",
    "; tentando novamente…": "; versuche es noch einmal...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"assets/flags/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat – Sitzung {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "Die API muss für jede Nachricht eine eindeutige ID bereitstellen.",
    "A API retornou uma resposta muito grande.": "Die API hat eine sehr große Antwort zurückgegeben.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "Port 19348 ist belegt. Schließen Sie eine weitere Spotify-Autorisierung und versuchen Sie es erneut.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "Die Vorschau verwendet die echte Musik. Nur „Speichern“ wendet die Änderungen auf die OBS-Quelle an.",
    "A sessão YouTube demorou para responder.": "Die YouTube-Sitzung reagierte langsam.",
    "API personalizada HTTP {0}": "{0} Benutzerdefinierte HTTP-API",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Öffnen Sie die dedizierte SR-Sitzung in Chrome/Edge und melden Sie sich bei Bedarf bei YouTube an. Die Sitzung wird automatisch wiederverwendet und synchronisiert. Sie müssen nicht nach Cookies suchen oder in Ordnern zwischenspeichern. YouTube-Einschränkungen erfordern möglicherweise eine erneute Authentifizierung oder verhindern einige Titel.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Öffnen Sie das Spotify Developer Dashboard und melden Sie sich mit Ihrem Konto an. Anwendungen im Entwicklungsmodus erfordern Premium vom Eigentümer und autorisierten Benutzern im Panel.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "Öffnet den Player mit seinem eigenen Namen: kaia_sr.exe oder kaia_voz.exe.",
    "Abrir HUD original": "Original-HUD öffnen",
    "Abrir HUD padrão": "Standard-HUD öffnen",
    "Abrir HUD personalizado": "Benutzerdefiniertes HUD öffnen",
    "Abrir configurações / liberar cliques": "Öffnen Sie Einstellungen / Release-Klicks",
    "Abrir overlay": "Overlay öffnen",
    "Abrir painel Spotify": "Öffnen Sie das Spotify-Panel",
    "Abrir pop-up": "Popup öffnen",
    "Abrir prévia desta fonte": "Vorschau dieser Schriftart öffnen",
    "Aceitar pedidos !sr das lives": "Akzeptieren Sie !sr-Anfragen von Leben",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "Sucht das Video, das dem Namen am nächsten kommt. Link = verwendet die ID. Name = ytsearch-Suche.",
    "Adicionar faixa à playlist de fundo": "Titel zur Hintergrund-Playlist hinzufügen",
    "Adicionar pedido SR": "SR-Bestellung hinzufügen",
    "Adicionar playlist": "Playlist hinzufügen",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "URL als Browserquelle in OBS hinzufügen. Lassen Sie Kaia Chat geöffnet, auch wenn das Fenster ausgeblendet ist.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "Widget-URLs hinzufügen, die in OBS verwendet werden. Streamlabs, StreamElements oder maßgeschneiderter Service. Jede Schriftart hat ihren eigenen Namen/ihre eigene Plattform. Widgets sind stummgeschaltet; Der erkannte Text wird am Reader-Ausgang nur gelesen. Durch die Aktivierung von Alarmquellen werden auch Warnungen aktiviert, wenn die normale Anzeige deaktiviert ist.",
    "Aguardando pedido !sr": "Warten auf !sr-Bestellung",
    "Alertas": "Benachrichtigungen",
    "Alertas para o streamer": "Benachrichtigungen für den Streamer",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "Einige temporäre Audiodaten werden verwendet. Die Reinigung wird bei der nächsten Öffnung wiederholt.",
    "Alguém": "Jemand",
    "Alt": "Alt",
    "Alta prioridade": "Hohe Priorität",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "Hohe Priorität liest alle Nachrichten und rückt nach Beendigung der aktuellen Rede an den Anfang der Warteschlange. Normale und niedrige Priorität haben unterschiedliche Zählungen. Um die Live-Übertragung zu ermöglichen, werden alte Nachrichten, einschließlich Prioritätsnachrichten, entsprechend der maximalen Verzögerung verworfen. In einer vollen Warteschlange verlassen die Ältesten mit der niedrigsten Priorität zuerst die Warteschlange. Die Pause zählt ab Beginn der Vorbereitung, ohne dass nach jeder Rede eine Pause eingefügt wird. Der beim Herstellen einer Verbindung abgerufene Verlauf wird nicht gesprochen.",
    "Alternar play/pausa": "Wiedergabe/Pause umschalten",
