    "Clique Salvar minhas credenciais, depois Conectar Spotify. Autorize no navegador oficial e volte ao Kaia Chat.": "Klicken Sie auf „Meine Anmeldeinformationen speichern“ und dann auf „Spotify verbinden“. Autorisieren Sie im offiziellen Browser und kehren Sie zu Kaia Chat zurück.",
