    "Compacto": "Kompakt",
    "Compatível com texto HTML acessível. Conteúdo em canvas, imagem/vídeo ou iframe de outro domínio pode não ser legível. Não é OCR e não identifica eventos ausentes do widget. Use o botão de teste do seu serviço após salvar. Não compartilhe seus URLs privados.": "Unterstützt barrierefreien HTML-Text. Canvas-, Bild-/Video- oder Iframe-Inhalte einer anderen Domain sind möglicherweise nicht lesbar. Es ist keine OCR und identifiziert keine fehlenden Widget-Ereignisse. Benutzen Sie nach dem Speichern die Schaltfläche „Service testen“. Geben Sie Ihre privaten URLs nicht weiter.",
