    "Nas configurações da aplicação, copie o Client ID para o campo desta aba. O fluxo PKCE de aplicativo desktop dispensa Client Secret; o campo opcional permite guardar o seu, se utilizado.": "Kopieren Sie in den Anwendungseinstellungen die Client-ID in das Feld auf dieser Registerkarte. Für den PKCE-Fluss der Desktop-Anwendung ist kein Client-Geheimnis erforderlich. Mit dem optionalen Feld können Sie Ihr eigenes Feld speichern, sofern es verwendet wird.",
