    "Não foi possível tocar o som. Escolha e salve a saída do leitor na aba Leitor.": "Der Ton kann nicht abgespielt werden. Wählen Sie die Reader-Ausgabe auf der Registerkarte „Reader“ aus und speichern Sie sie.",
    "Não li a playlist:": "Ich habe die Playlist nicht gelesen:",
    "Não li a playlist: {0}": "Ich habe die Playlist {0} nicht gelesen",
    "O SR está no mudo, independentemente do volume salvo.": "SR wird unabhängig von der gespeicherten Lautstärke stummgeschaltet.",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify veröffentlicht den Track in HUDs; Die Wiedergabe wird in der Spotify-App fortgesetzt. Autorisierung und Token werden automatisch erneuert. SR spielt Anfragen von YouTube ab, lädt kein Audio von Spotify herunter.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "Die Sicherung umfasst Nachrichten, die von allen Plattformen empfangen wurden, einschließlich Spitznamen, die durch blockierte Chats verborgen wurden. Durch das Ausblenden wird lediglich der Bildschirm gelöscht.",
    "O campo da lista de mensagens não contém um array JSON.": "Das Nachrichtenlistenfeld enthält kein JSON-Array.",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "Der Befehl {0} hat zu lange gedauert. Die anderen Steuerelemente bleiben verfügbar; versuchen Sie es erneut.",
    "O decodificador não produziu áudio.": "Der Decoder hat kein Audio erzeugt.",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "Das Messgerät verwendet Audio vom ausgewählten Ausgang. Möglicherweise werden auch andere Töne auf demselben Gerät angezeigt. Der Editor behält Themen, CSS, RGB und Balken aus dem Originalpaket bei.",
    "O motor de áudio demorou para iniciar.": "Die Audio-Engine startete langsam.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "Der Browser hat die dedizierte Sitzung nicht freigegeben. Schließen Sie dieses YouTube-Fenster und versuchen Sie erneut, eine Verbindung herzustellen.",
    "O navegador recusou a sincronização da sessão.": "Der Browser weigerte sich, die Sitzung zu synchronisieren.",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "Das zweite Overlay zeigt die gleichen Daten wie SR/Spotify. Bearbeiten Sie hier das Erscheinungsbild. Das Standard-HUD bleibt verfügbar.",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "OBS → Browser-Schriftart hinzufügen. Verwenden Sie zunächst 800 × 320 und schneiden Sie es entsprechend dem Layout zu. Transparenter Hintergrund; Kein Chroma-Key erforderlich.",
    "Oculte mensagens e sons de nicks específicos": "Nachrichten und Sounds von bestimmten Nicks ausblenden",
