    "Opcional: recomendado usar PKCE sem segredo": "Optional: Es wird empfohlen, PKCE ohne Geheimnis zu verwenden",
    "Operador": "Betreiber",
    "Ordem manual salva; aleatório desativado.": "Manuelle Bestellung gespeichert; zufällig deaktiviert.",
