    "PASS SCHMOOPIIE": "PASS SCHMOOPIIE",
    "PRÉVIA AO VIVO ·": "LIVE-VORSCHAU ·",
    "Padrão do Windows": "Windows-Standard",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "Um nur über das Headset zu hören, wählen Sie eine Ausgabe, die nicht in OBS erfasst wird. Das Lesen wechselt nicht zur Standardausgabe, wenn das ausgewählte Gerät nicht verfügbar ist. Edge Voice erfordert Internet.",
