    "Preservar as cores dos nomes de usuário": "Farben des Benutzernamens beibehalten",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "Audio-Datenschutz: SR-Songs werden ohne permanenten Download übertragen. Reden verwenden temporäre Dateien, die nach der Verwendung und beim Schließen gelöscht werden. Reste eines Interrupts werden beim nächsten Start der Audio-Engine bereinigt. Die von Ihnen gewählten Sounds und das TXT-Backup bleiben erhalten.",
