    "Salve e ative a fonte antes de abrir a prévia.": "Speichern und aktivieren Sie die Quelle, bevor Sie die Vorschau öffnen.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "Speichern Sie mit der SR Save-Taste. Anfragen werden als nächstes nach dem aktuellen Titel und vor den Titeln in der Wiedergabeliste abgespielt. Die Beschränkungen gelten für neue Einträge und entfernen bereits akzeptierte Songs nicht. Chattöne und -aufforderungen verwenden die Reader-Ausgabe; Musik verwendet den SR-Ausgang. OBS sollte nur SR-Ausgaben/-Prozesse erfassen, um Warnungen privat zu halten.",
    "Salve seu Client ID primeiro.": "Speichern Sie zuerst Ihre Kunden-ID.",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "Gespeichert. Das OBS-Overlay wird innerhalb von zwei Sekunden aktualisiert.",
    "Saída SR indisponível. Selecione novamente a saída da música.": "SR-Ausgabe nicht verfügbar. Wählen Sie die Musikausgabe erneut aus.",
