    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "Aktualisierte Audioausgänge. Wählen Sie die Leseausgabe aus.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "Einzelne Audioausgänge. SR und Kaia verwenden unterschiedliche Geräte. Verwenden Sie nicht ffmpeg -f wasapi (viele Windows-Builds verfügen nicht über diesen Muxer). Standard = ffplay. Ausgewähltes Gerät = ffmpeg PCM + Soundgerät.",
