    "Tom de teste enviado à saída do SR. Confirme se você ouviu; este teste não usa YouTube nem os alertas.": "Testton, der an den SR-Ausgang gesendet wird. Bestätigen Sie, dass Sie gehört haben; Dieser Test verwendet weder YouTube noch die Warnungen.",
    "Toque uma música no Spotify. A faixa aparecerá aqui e nos HUDs. Não envie suas chaves ou tokens ao GitHub.": "Spielen Sie ein Lied auf dem Spotify ab. Das Banner wird hier und auf den HUDs erscheinen. Senden Sie Ihre Schlüssel oder Token nicht an GitHub.",
