    "Um nick por linha, ou separe por vírgulas. Aceita @ e ignora maiúsculas/minúsculas. O bloqueio é apenas neste overlay.": "Ein Spitzname pro Zeile oder durch Kommas getrennt. Akzeptiert @ und ignoriert Groß-/Kleinschreibung. Die Blockierung erfolgt nur auf diesem Overlay.",
