    "Use um endpoint JSON público. Links de live e widgets HTML não são lidos automaticamente; cada serviço precisa permitir acesso às mensagens.": "Verwenden Sie einen öffentlichen JSON-Endpunkt. Live-Links und HTML-Widgets werden nicht automatisch gelesen; Jeder Dienst muss den Zugriff auf Nachrichten ermöglichen.",
    "Use uma API HTTPS pública ou HTTP local, sem senha na URL.": "Verwenden Sie ein öffentliches HTTPS oder eine lokale HTTP-API ohne Passwort in der URL.",
    "Use ↑/↓ ou informe a posição para organizar manualmente. A ordem de cada lista é independente; ordenar desativa o aleatório.": "Verwenden Sie ↑/↓ oder geben Sie die Position zum manuellen Anordnen ein. Die Reihenfolge jeder Liste ist unabhängig; Reihenfolge deaktiviert Zufall.",
