    "Vídeos complementares em inglês podem mostrar uma interface antiga. Para a URL e o fluxo atuais, siga este tutorial e o guia oficial.": "Englische Zusatzvideos zeigen möglicherweise eine alte Benutzeroberfläche. Befolgen Sie für die aktuelle URL und den aktuellen Ablauf dieses Tutorial und den offiziellen Leitfaden.",
