    "YouTube exige login para este acesso. Na aba SR, clique Conectar YouTube, faça login na sessão dedicada e depois Testar acesso.": "YouTube erfordert eine Anmeldung für diesen Zugriff. Klicken Sie auf der Registerkarte „SR“ auf „YouTube verbinden“, melden Sie sich bei der dedizierten Sitzung an und klicken Sie dann auf „Zugriff testen“.",
    "YouTube limitou as requisições (HTTP 429). SR aguardando 10 minutos antes de tentar novamente.": "YouTube eingeschränkte Anfragen (HTTP 429). SR wartet 10 Minuten, bevor es erneut versucht wird.",
