    ": texto do widget incorporado encontrado; aguardando alerta e término da mídia.": ": trovato testo widget incorporato; in attesa di avviso e fine dei media.",
    "; tentando novamente…": "; riprovare...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"risorse/flag/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat — sessione {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "L'API deve fornire un ID univoco per ciascun messaggio.",
    "A API retornou uma resposta muito grande.": "L'API ha restituito una risposta molto ampia.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "La porta 19348 è occupata. Chiudere un'altra autorizzazione Spotify e riprovare.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "L'anteprima utilizza la musica reale. Solo Salva applica le modifiche alla sorgente OBS.",
    "A sessão YouTube demorou para responder.": "La sessione YouTube ha risposto lentamente.",
    "API personalizada HTTP {0}": "{0} API HTTP personalizzata",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Apri la sessione SR dedicata in Chrome/Edge e accedi a YouTube se necessario. La sessione viene riutilizzata e sincronizzata automaticamente. Non è necessario cercare cookie o memorizzare nella cache le cartelle. Le restrizioni di YouTube potrebbero richiedere la riautenticazione o impedire alcune tracce.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Apri la dashboard dello sviluppatore Spotify e accedi con il tuo account. Le applicazioni in modalità sviluppo richiedono Premium dal proprietario e dagli utenti autorizzati nel pannello.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "Apre il lettore con il proprio nome: kaia_sr.exe o kaia_voz.exe.",
    "Abrir HUD original": "Apri l'HUD originale",
    "Abrir HUD padrão": "Apre l'HUD predefinito",
    "Abrir HUD personalizado": "Apri l'HUD personalizzato",
    "Abrir configurações / liberar cliques": "Apri Impostazioni/Rilascia clic",
    "Abrir overlay": "Apri sovrapposizione",
    "Abrir painel Spotify": "Apri il pannello Spotify",
    "Abrir pop-up": "Apri il popup",
    "Abrir prévia desta fonte": "Apri l'anteprima di questo carattere",
    "Aceitar pedidos !sr das lives": "Accetta richieste !sr dalle vite",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "Trova il video più vicino al nome. Link = utilizza l'id. Nome = ricerca ytsearch.",
    "Adicionar faixa à playlist de fundo": "Aggiungi traccia alla playlist di sottofondo",
    "Adicionar pedido SR": "Aggiungi ordine SR",
    "Adicionar playlist": "Aggiungi playlist",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "Aggiungi URL come origine del browser in OBS. Mantieni Kaia Chat aperto, anche con la finestra nascosta.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "Aggiungi gli URL dei widget utilizzati in OBS. Streamlabs, StreamElements o servizio personalizzato. Ogni carattere ha il proprio nome/piattaforma. I widget sono disattivati; il testo riconosciuto viene letto solo sull'uscita Reader. L'abilitazione delle fonti di avviso abilita anche gli avvisi con la lettura normale disattivata.",
    "Aguardando pedido !sr": "In attesa dell'ordine !sr",
    "Alertas": "Avvisi",
    "Alertas para o streamer": "Avvisi per lo streamer",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "Sono in uso alcuni audio temporanei. La pulizia verrà ripetuta alla prossima apertura.",
    "Alguém": "Qualcuno",
    "Alt": "Alt",
    "Alta prioridade": "Priorità alta",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "La priorità alta legge tutti i messaggi e si sposta in prima fila dopo aver terminato il discorso corrente. La priorità normale e quella bassa hanno conteggi separati. Per seguire la diretta i vecchi messaggi vengono scartati in base al ritardo massimo, compresi quelli prioritari. In una coda piena, i più anziani con la priorità più bassa partono per primi. La pausa conta dall'inizio della preparazione, senza aggiungere una pausa dopo ogni discorso. La cronologia recuperata al momento della connessione non viene parlata.",
    "Alternar play/pausa": "Attiva/disattiva riproduzione/pausa",
