    "Não li a playlist: {0}": "Non ho letto la playlist: {0}",
    "O SR está no mudo, independentemente do volume salvo.": "SR viene disattivato indipendentemente dal volume salvato.",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify pubblica la traccia sugli HUD; la riproduzione continua nell'app Spotify. L'autorizzazione e i token vengono rinnovati automaticamente. SR riproduce le richieste da YouTube, non scarica l'audio da Spotify.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "Il backup include i messaggi ricevuti da tutte le piattaforme, compresi i nickname nascosti dalle chat bloccate. La dissolvenza cancella solo lo schermo.",
    "O campo da lista de mensagens não contém um array JSON.": "Il campo dell'elenco dei messaggi non contiene un array JSON.",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "Il comando {0} ha impiegato troppo tempo. Gli altri controlli rimangono disponibili; riprova.",
    "O decodificador não produziu áudio.": "Il decoder non produceva audio.",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "Lo strumento utilizza l'audio dall'uscita selezionata. Potrebbero apparire anche altri suoni sullo stesso dispositivo. L'editor conserva temi, CSS, RGB e barre del pacchetto originale.",
    "O motor de áudio demorou para iniciar.": "Il motore audio si avviava lentamente.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "Il browser non ha rilasciato la sessione dedicata. Chiudi questa finestra YouTube e prova a connetterti di nuovo.",
    "O navegador recusou a sincronização da sessão.": "Il browser ha rifiutato di sincronizzare la sessione.",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "La seconda sovrapposizione mostra gli stessi dati di SR/Spotify. Modifica l'aspetto qui; l'HUD standard rimane disponibile.",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "OBS → aggiungi carattere browser. Inizialmente utilizza 800×320 e ritaglia in base al layout. Sfondo trasparente; Non è necessario il chroma key.",
