    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "Privacy audio: i brani SR vengono trasmessi senza download permanente. I discorsi utilizzano file temporanei, cancellati dopo l'uso e alla chiusura. I residui di un'interruzione vengono eliminati al successivo avvio del motore audio. I suoni scelti da te e il backup TXT vengono conservati.",
    "Proteção de credenciais indisponível neste Windows.": "Protezione delle credenziali non disponibile su questo Windows.",
