    "Salve e ative a fonte antes de abrir a prévia.": "Salva e attiva la sorgente prima di aprire l'anteprima.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "Salvare utilizzando il pulsante SR Save. Le richieste vengono riprodotte dopo la traccia corrente, prima dei brani nella playlist. I limiti si applicano ai nuovi inserimenti e non rimuovono i brani già accettati. I suoni e i suggerimenti della chat utilizzano l'output di Reader; la musica utilizza l'uscita SR. OBS dovrebbe acquisire solo l'output/processo SR per mantenere privati ​​gli avvisi.",
    "Salve seu Client ID primeiro.": "Salva prima il tuo ID cliente.",
