    "Saída selecionada indisponível; áudio não enviado à saída padrão.": "Uscita selezionata non disponibile; audio non inviato all'uscita standard.",
    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "Uscite audio aggiornate. Seleziona l'uscita di lettura.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "Uscite audio singole. SR e Kaia utilizzano dispositivi diversi. Non utilizzare ffmpeg -f wasapi (molte build di Windows non hanno questo muxer). Impostazione predefinita = ffplay. Dispositivo scelto = ffmpeg PCM + dispositivo audio.",
