    ": texto do widget incorporado encontrado; aguardando alerta e término da mídia.": ": найден встроенный текст виджета; ожидание оповещения и окончания мультимедиа.",
    "; tentando novamente…": "; пробую еще раз...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"assets/flags/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat — сеанс {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "API должен предоставить уникальный идентификатор для каждого сообщения.",
    "A API retornou uma resposta muito grande.": "API вернул очень большой ответ.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "Порт 19348 занят. Закройте еще одну авторизацию Spotify и повторите попытку.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "В предварительном просмотре используется настоящая музыка. Только «Сохранить» применяет изменения к источнику OBS.",
    "A sessão YouTube demorou para responder.": "Сеанс YouTube отвечал медленно.",
    "API personalizada HTTP {0}": "Пользовательский HTTP API {0}",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Откройте выделенный сеанс SR в Chrome/Edge и при необходимости войдите в YouTube. Сеанс автоматически повторно используется и синхронизируется. Не нужно искать файлы cookie или кэш в папках. Ограничения YouTube могут потребовать повторной аутентификации или предотвратить некоторые треки.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Откройте панель разработчика Spotify и войдите под своей учетной записью. Приложения в режиме разработки требуют Premium от владельца и авторизованных пользователей в панели.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "Откройте плеер с его собственным именем: kaia_sr.exe или kaia_voz.exe.",
    "Abrir HUD original": "Открыть оригинальный HUD",
    "Abrir HUD padrão": "Открыть стандартный HUD",
    "Abrir HUD personalizado": "Открыть пользовательский HUD",
