    "Aceitar pedidos !sr das lives": "Принимайте заказы !sr от Lives",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "Найдите видео, наиболее близкое к названию. Ссылка = использует идентификатор. Имя = ytsearch search.",
    "Adicionar faixa à playlist de fundo": "Добавить трек в фоновый плейлист",
    "Adicionar pedido SR": "Добавить заказ на поставку",
    "Adicionar playlist": "Добавить плейлист",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "Добавьте URL-адрес в качестве источника браузера в OBS. Держите Kaia Chat открытым, даже если окно скрыто.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "Добавьте URL-адреса виджетов, используемые в OBS. Streamlabs, StreamElements или индивидуальный сервис. Каждый шрифт имеет свое имя/платформу. Виджеты отключены; распознанный текст читается только на выходе Reader. Включение источников оповещений также включает предупреждения с отключенным обычным чтением.",
    "Aguardando pedido !sr": "Жду заказ !sr",
