    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "Используется временное аудио. Очистка будет повторена при следующем открытии.",
    "Alguém": "Кто-то",
    "Alt": "Альтернативный вариант",
    "Alta prioridade": "Высокий приоритет",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "Высокий приоритет читает все сообщения и перемещается в начало очереди после завершения текущей речи. Обычный и низкий приоритет имеют отдельные подсчеты. Для отслеживания в прямом эфире старые сообщения отбрасываются по максимальной задержке, включая приоритетные. При полной очереди первыми уходят самые старые с наименьшим приоритетом. Перерыв отсчитывается с начала подготовки, без добавления паузы после каждого выступления. История, полученная при подключении, не произносится.",
