    "Clique Salvar minhas credenciais, depois Conectar Spotify. Autorize no navegador oficial e volte ao Kaia Chat.": "Нажмите «Сохранить мои учетные данные», затем «Подключить Spotify». Авторизуйтесь в официальном браузере и вернитесь в Kaia Chat.",
