    "O SR está no mudo, independentemente do volume salvo.": "Звук SR отключен независимо от сохраненной громкости.",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify публикует трек в HUD; воспроизведение продолжается в приложении Spotify. Авторизация и токены автоматически продлеваются. SR воспроизводит запросы от YouTube, не загружает звук от Spotify.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "В резервную копию входят сообщения, полученные со всех платформ, включая никнеймы, скрытые заблокированными чатами. Затухание только очищает экран.",
    "O campo da lista de mensagens não contém um array JSON.": "Поле списка сообщений не содержит массив JSON.",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "Команда {0} выполнялась слишком долго. Остальные элементы управления остаются доступными; Попробуйте еще раз.",
    "O decodificador não produziu áudio.": "Декодер не воспроизводит звук.",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "Измеритель использует звук с выбранного выхода. Также могут появляться другие звуки на том же устройстве. Редактор сохраняет темы, CSS, RGB и панели из исходного пакета.",
    "O motor de áudio demorou para iniciar.": "Звуковой движок запускался медленно.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "Браузер не освободил выделенный сеанс. Закройте это окно YouTube и повторите попытку подключения.",
    "O navegador recusou a sincronização da sessão.": "Браузер отказался синхронизировать сеанс.",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "Второе наложение показывает те же данные, что и SR/Spotify. Отредактируйте внешний вид здесь; стандартный HUD остается доступным.",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "ПРИМЕЧАНИЕ → добавьте шрифт браузера. Изначально используйте размер 800×320 и обрезайте по макету. Прозрачный фон; Хромакей не нужен.",
    "Oculte mensagens e sons de nicks específicos": "Скрыть сообщения и звуки от определенных ников",
    "Opacidade do fundo (%)": "Непрозрачность фона (%)",
    "Opcional: recomendado usar PKCE sem segredo": "Необязательно: рекомендуется использовать PKCE без секрета.",
    "Operador": "Оператор",
    "Ordem manual salva; aleatório desativado.": "Ручной заказ сохранен; случайный отключен.",
    "Os avisos usam a saída salva no Leitor.": "Предупреждения используют выходные данные, сохраненные в Reader.",
    "PASS SCHMOOPIIE": "ПРОЙДИТЕ ШМУПИЕ",
    "PRÉVIA AO VIVO ·": "ПРЯМОЕ ПРОСМОТР ·",
    "Padrão do Windows": "Стандарт Windows",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "Чтобы слушать только через гарнитуру, выберите выход, который не захватывается в OBS. Чтение не переключается на стандартный вывод, если выбранное устройство становится недоступным. Edge Voice требует подключения к Интернету.",
    "Parar": "Стоп",
    "Parar e limpar todas as filas": "Parar e limpar todas as filas",
    "Parar leitura": "Хватит читать",
    "Pare a leitura atual antes de testar a voz.": "Pare a leitura atual antes de testar a voz.",
    "Pare a música antes de testar a saída do SR.": "Остановите музыку перед проверкой выхода SR.",
    "Parece um Popen: poll/terminate/kill/wait.": "Это выглядит как Popen: опрос/завершить/убить/подождать.",
    "Pausado": "Приостановлено",
    "Pausar": "Пауза",
    "Pausar música": "Пауза музыки",
    "Pedido pendente colocado novamente na fila.": "Отложенный ордер снова помещен в очередь.",
    "Pedido:": "Заказ:",
    "Pedidos !sr ativos.": "Активные заказы !sr.",
    "Pedidos !sr nome da música ou !sr link do YouTube, recebidos nos chats conectados, entram na fila. Ative abaixo para aceitar pedidos. Usuários bloqueados e mensagens históricas são ignorados.": "Запросы на название песни !sr или ссылку !sr YouTube, полученные в подключенных чатах, попадают в очередь. Активируйте ниже, чтобы принимать заказы. Заблокированные пользователи и исторические сообщения игнорируются.",
    "Pedidos SR ·": "Заказы СР ·",
    "Pedidos das lives desativados.": "Живые запросы отключены.",
    "Pega URL de áudio pra tocar. Não baixa arquivo.": "Получите URL-адрес аудио для воспроизведения. Не скачивает файл.",
