    "Playlist de fundo: {0} faixas. !sr do chat fura a fila.": "Фоновый плейлист: треки {0}. !sr из чата выходит из очереди.",
    "Playlist do YouTube": "Плейлист YouTube",
    "Playlist só o admin cola no player do SR (botão playlist).": "Только администратор может вставить плейлист в СР плеер (кнопка плейлиста).",
    "Pode voltar ao Kaia Chat.": "Вы можете вернуться в Kaia Chat.",
    "Português": "португальский",
    "Posição da música": "Музыкальная позиция",
    "Posição da música na aba Chat": "Позиция музыки во вкладке Чат",
    "Posição de": "Позиция",
    "Preparando voz de {0} · {1} na fila · {2} descartadas pelo limite/filtro": "Подготовка голоса из {0} · {1} в очереди · {2} отброшен ограничением/фильтром",
    "Preparando/reproduzindo aviso": "Подготовка/воспроизведение уведомления",
    "Preservar as cores dos nomes de usuário": "Сохранять цвета имени пользователя",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "Конфиденциальность звука: песни SR передаются без постоянной загрузки. Выступления используют временные файлы, удаляемые после использования и при закрытии. Остатки прерывания удаляются при следующем запуске звукового движка. Выбранные вами звуки и резервная копия TXT сохраняются.",
    "Proteção de credenciais indisponível neste Windows.": "Защита учетных данных недоступна в этой Windows.",
    "Prévia alterada · salve para aplicar no OBS.": "Предварительный просмотр изменен · сохраните, чтобы применить к OBS.",
    "Prévia ao vivo": "Предварительный просмотр в реальном времени",
