    "RGB + reação ao áudio real do SR": "RGB + реакция на реальный звук SR",
    "RGB animado · ciclo de cores": "Анимированный RGB · цветовой цикл",
    "Reação usa a energia e os picos do áudio do SR com saída explícita. Sem sinal medido (Spotify/player padrão), mantém apenas o ciclo RGB; não simula batidas.": "Реакция использует энергию и пики звука SR с явным выходом. Без измеряемого сигнала (Spotify/стандартный проигрыватель) поддерживается только цикл RGB; не имитирует ритмы.",
    "Redirect URI — copie exatamente": "URI перенаправления — скопируйте точно",
