    "Revise os URLs e seletores das fontes de alertas.": "Просмотрите URL-адреса источников оповещений и селекторы.",
    "Runtime de áudio ausente. Use o ZIP completo ou prepare .runtime.": "Отсутствует время выполнения звука. Используйте полный ZIP-архив или подготовьте .runtime.",
