    "Salvar aparência": "Сохранить внешний вид",
    "Salvar atalhos globais": "Сохранение глобальных ярлыков",
    "Salvar bloqueios": "Сохранить замки",
    "Salvar e conectar": "Сохранить и подключить",
    "Salvar e monitorar fontes": "Сохраняйте и отслеживайте шрифты",
    "Salvar leitura": "Сохранить чтение",
    "Salvar minhas credenciais": "Сохранить мои учетные данные",
    "Salvar no overlay": "Сохранить для наложения",
    "Salvar temporizador": "Сохранить таймер",
    "Salvar widget e atualizar prévia": "Сохранить виджет и обновить предварительный просмотр",
    "Salve e ative a fonte antes de abrir a prévia.": "Сохраните и активируйте шрифт перед открытием предварительного просмотра.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "Сохраните с помощью кнопки Save SR. Запросы на воспроизведение располагаются после текущего трека, перед песнями в плейлисте. Ограничения распространяются на новые записи и не удаляют уже принятые песни. Звуки и подсказки чата используют вывод Reader; музыка использует выход SR. OBS должен фиксировать только выходные данные/процесс SR, чтобы сохранить конфиденциальность предупреждений.",
    "Salve seu Client ID primeiro.": "Сначала сохраните свой идентификатор клиента.",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "Сохранено. Наложение OBS обновляется в течение двух секунд.",
    "Saída SR indisponível. Selecione novamente a saída da música.": "Выход SR недоступен. Снова выберите музыкальный выход.",
    "Saída da leitura": "Чтение вывода",
    "Saída da música": "Музыкальный выход",
    "Saída da soundbar": "Выход на звуковую панель",
    "Saída de leitura indisponível; selecione novamente o dispositivo.": "Чтение данных недоступно; выберите устройство еще раз.",
    "Saída de áudio indisponível. Pedido preservado.": "Аудиовыход недоступен. Порядок сохранен.",
    "Saída padrão": "Стандартный вывод",
    "Saída padrão do Windows": "Стандартный вывод Windows",
    "Saída selecionada indisponível; áudio não enviado à saída padrão.": "Выбранный результат недоступен; звук не отправляется на стандартный вывод.",
    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "Обновлены аудиовыходы. Выберите выход для чтения.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "Уникальные аудиовыходы. SR и Kaia используют разные устройства. Не используйте ffmpeg -f wasapi (во многих сборках Windows этот мультиплексор отсутствует). По умолчанию = ffplay. Выбранное устройство = ffmpeg PCM + звуковое устройство.",
    "Scripts": "Скрипты",
    "Segredo protegido já salvo; vazio mantém o atual": "Защищенный секрет уже сохранен; пусто сохраняет актуальность",
    "Selecione a URL acima para copiar.": "Выберите URL-адрес выше для копирования.",
    "Selecione a saída do leitor: os sons do chat usam essa saída privada.": "Выберите выход для чтения: звуки чата используют этот частный выход.",
