    "Selecione e salve a saída de áudio do Leitor primeiro.": "Сначала выберите и сохраните аудиовыход Reader.",
    "Selecione e salve a saída de áudio primeiro.": "Сначала выберите и сохраните аудиовыход.",
    "Selecione e salve a saída do Leitor.": "Выберите и сохраните вывод Reader.",
    "Seletor CSS do texto": "Текстовый CSS-селектор",
    "Seletor do texto do alerta": "Выбор текста оповещения",
    "Seletores: #box, #lab, #tit, #who, .bar, #fill, #tempo. Não altera áudio ou reprodução.": "Селекторы: #box, #lab, #tit, #who, .bar, #fill, #tempo. Не изменяет звук или воспроизведение.",
    "Seletores: #feed, .message, .user, .message-text, .platform e [data-platform=\"kick\"]. O tempo das mensagens segue a aba Chat. O CSS é aplicado ao salvar.": "Селекторы: #feed, .message, .user, .message-text, .platform и [data-platform=\"kick\"]. Время отправки сообщений соответствует вкладке «Чат». CSS применяется при сохранении.",
    "Sem login • Emotes nativos + 7TV, BTTV e FFZ públicos": "Без входа • Собственные смайлы + общедоступные 7TV, BTTV и FFZ",
