    "Use campos JSON separados por ponto, sem código.": "Используйте поля JSON, разделенные точками, без кода.",
    "Use um endpoint JSON público. Links de live e widgets HTML não são lidos automaticamente; cada serviço precisa permitir acesso às mensagens.": "Используйте общедоступную конечную точку JSON. Живые ссылки и HTML-виджеты не читаются автоматически; каждая служба должна разрешать доступ к сообщениям.",
    "Use uma API HTTPS pública ou HTTP local, sem senha na URL.": "Используйте общедоступный HTTPS или локальный HTTP API без пароля в URL-адресе.",
    "Use ↑/↓ ou informe a posição para organizar manualmente. A ordem de cada lista é independente; ordenar desativa o aleatório.": "Используйте ↑/↓ или введите позицию для организации вручную. Порядок каждого списка независим; порядок отключает случайный.",
