    "Vídeos complementares em inglês podem mostrar uma interface antiga. Para a URL e o fluxo atuais, siga este tutorial e o guia oficial.": "Дополнительные видеоролики на английском языке могут показывать старый интерфейс. Чтобы узнать текущий URL-адрес и порядок действий, следуйте этому руководству и официальному руководству.",
