    "YouTube acessível; áudio resolvido sem reproduzir.": "доступный YouTube; Звук разрешился без воспроизведения.",
    "YouTube exige login para este acesso. Na aba SR, clique Conectar YouTube, faça login na sessão dedicada e depois Testar acesso.": "YouTube требует входа в систему для этого доступа. На вкладке SR нажмите «Подключить YouTube», войдите в выделенный сеанс, а затем «Проверить доступ».",
    "YouTube limitou as requisições (HTTP 429). SR aguardando 10 minutos antes de tentar novamente.": "Ограниченные запросы YouTube (HTTP 429). SR ждет 10 минут, прежде чем повторить попытку.",
