    "30 segundos": "30 ثانية",
    "5 minutos": "5 دقائق",
    ": alerta identificado; aguardando o fim para falar.": ": تم تحديد التنبيه؛ في انتظار نهاية الكلام.",
    ": falha ao carregar. Verifique o URL do widget.": ": فشل التحميل. تحقق من عنوان URL للأداة.",
    ": monitorando texto HTML; dispare um alerta de teste no serviço.": ": مراقبة نص HTML؛ إطلاق تنبيه اختبار على الخدمة.",
    ": não foi possível abrir a fonte.": ": غير قادر على فتح المصدر.",
    ": seletor CSS inválido. Corrija o campo do texto do alerta.": ": محدد CSS غير صالح. قم بتصحيح حقل نص التنبيه.",
    ": texto do widget incorporado encontrado; aguardando alerta e término da mídia.": ": تم العثور على نص عنصر واجهة المستخدم المضمن؛ في انتظار التنبيه وانتهاء الوسائط.",
    "; tentando novamente…": "; حاول مرة أخرى...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"assets/flags/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat — جلسة {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "تحتاج واجهة برمجة التطبيقات (API) إلى توفير معرف فريد لكل رسالة.",
    "A API retornou uma resposta muito grande.": "أعادت واجهة برمجة التطبيقات (API) استجابة كبيرة جدًا.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "المنفذ 19348 مشغول. أغلق ترخيص Spotify آخر وحاول مرة أخرى.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "تستخدم المعاينة الموسيقى الحقيقية. يطبق الحفظ فقط التغييرات على مصدر OBS.",
    "A sessão YouTube demorou para responder.": "كانت جلسة YouTube بطيئة في الاستجابة.",
    "API personalizada HTTP {0}": "{0} Custom HTTP API",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "افتح جلسة SR المخصصة في Chrome/Edge وقم بتسجيل الدخول إلى YouTube إذا لزم الأمر. تتم إعادة استخدام الجلسة ومزامنتها تلقائيًا. لا حاجة للبحث عن ملفات تعريف الارتباط أو ذاكرة التخزين المؤقت في المجلدات. قد تتطلب قيود YouTube إعادة المصادقة أو منع بعض المسارات.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "افتح لوحة تحكم المطور Spotify وقم بتسجيل الدخول باستخدام حسابك. تتطلب التطبيقات في وضع التطوير الحصول على Premium من المالك والمستخدمين المعتمدين في اللوحة.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "يفتح المشغل باسمه الخاص: kaia_sr.exe أو kaia_voz.exe.",
    "Abrir HUD original": "افتح شاشة HUD الأصلية",
    "Abrir HUD padrão": "فتح HUD الافتراضي",
    "Abrir HUD personalizado": "افتح HUD المخصص",
    "Abrir configurações / liberar cliques": "افتح الإعدادات / نقرات الإصدار",
    "Abrir overlay": "فتح التراكب",
    "Abrir painel Spotify": "افتح لوحة Spotify",
    "Abrir pop-up": "فتح النافذة المنبثقة",
    "Abrir prévia desta fonte": "فتح المعاينة لهذا الخط",
    "Aceitar pedidos !sr das lives": "قبول طلبات !sr من الأرواح",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "يبحث عن الفيديو الأقرب إلى الاسم. الرابط = يستخدم المعرف. الاسم = بحث ytsearch.",
    "Adicionar faixa à playlist de fundo": "إضافة المسار إلى قائمة التشغيل في الخلفية",
    "Adicionar pedido SR": "إضافة أمر SR",
    "Adicionar playlist": "إضافة قائمة التشغيل",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "أضف عنوان URL كمصدر للمتصفح في OBS. أبقِ Kaia Chat مفتوحًا، حتى مع إخفاء النافذة.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "أضف عناوين URL لعناصر واجهة المستخدم المستخدمة في OBS. Streamlabs أو StreamElements أو خدمة مخصصة. كل خط له اسمه/النظام الأساسي الخاص به. تم كتم صوت الأدوات؛ تتم قراءة النص الذي تم التعرف عليه فقط عند إخراج القارئ. يؤدي تمكين مصادر التنبيه أيضًا إلى تمكين التحذيرات مع إيقاف تشغيل القراءة العادية.",
    "Aguardando pedido !sr": "في انتظار طلب !sr",
    "Alertas": "التنبيهات",
    "Alertas para o streamer": "تنبيهات للقائم بالبث",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "بعض الصوت المؤقت قيد الاستخدام. سيتم تكرار التنظيف في الافتتاح التالي.",
    "Alguém": "شخص ما",
    "Alt": "بديل",
    "Alta prioridade": "أولوية عالية",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "الأولوية العليا لقراءة كافة الرسائل والانتقال إلى مقدمة قائمة الانتظار بعد الانتهاء من الكلام الحالي. الأولوية العادية والمنخفضة لها أعداد منفصلة. لمتابعة البث المباشر يتم تجاهل الرسائل القديمة حسب الحد الأقصى للتأخير بما في ذلك الرسائل ذات الأولوية. في قائمة الانتظار الكاملة، يغادر الأشخاص الأقدم ذوي الأولوية الأدنى أولاً. تحسب الاستراحة من بداية الإعداد، دون إضافة استراحة بعد كل خطاب. لا يتم نطق السجل الذي تم استرداده عند الاتصال.",
    "Alternar play/pausa": "تبديل التشغيل/الإيقاف المؤقت",
    "Alto contraste": "تباين عالي",
    "Altura da soundbar (px)": "ارتفاع مكبر الصوت (بيكسل)",
    "Amostragem: aguardando {0}/{1} mensagens.": "أخذ العينات: انتظار رسائل {0}/{1}.",
    "Anterior": "السابق",
    "Antonio · português BR": "أنطونيو · البرتغالية BR",
    "Aparência salva. Chats continuam conectados.": "تم حفظ المظهر. تظل الدردشات متصلة.",
    "Aplicar soundbar": "قم بتطبيق مكبر الصوت",
    "Arquivo de cookies não encontrado.": "لم يتم العثور على ملف تعريف الارتباط.",
    "Arquivo de layout inválido.": "ملف تخطيط غير صالح.",
    "Arquivo de som inválido.": "ملف صوت غير صالح.",
