    "Compatível com texto HTML acessível. Conteúdo em canvas, imagem/vídeo ou iframe de outro domínio pode não ser legível. Não é OCR e não identifica eventos ausentes do widget. Use o botão de teste do seu serviço após salvar. Não compartilhe seus URLs privados.": "يدعم نص HTML يمكن الوصول إليه. قد لا يكون محتوى اللوحة القماشية أو الصورة/الفيديو أو محتوى iframe من نطاق آخر قابلاً للقراءة. إنه ليس التعرف الضوئي على الحروف (OCR) ولا يحدد أحداث عنصر واجهة المستخدم المفقودة. استخدم زر اختبار الخدمة الخاصة بك بعد الحفظ. لا تشارك عناوين URL الخاصة بك.",
