    "Nas configurações da aplicação, copie o Client ID para o campo desta aba. O fluxo PKCE de aplicativo desktop dispensa Client Secret; o campo opcional permite guardar o seu, se utilizado.": "في إعدادات التطبيق، انسخ معرف العميل إلى الحقل الموجود في علامة التبويب هذه. لا يتطلب تدفق PKCE لتطبيق سطح المكتب سر العميل؛ يسمح لك الحقل الاختياري بحفظ حقلك، في حالة استخدامه.",
