    "Navegador dedicado aberto. Faça login no YouTube e depois teste o acesso.": "فتح متصفح مخصص. قم بتسجيل الدخول إلى YouTube ثم قم باختبار الوصول.",
    "Negrito": "جريئة",
    "Nenhum alerta recebido ainda. Salve a fonte e dispare um alerta de teste no serviço.": "لم يتم تلقي أي تنبيهات حتى الآن. احفظ المصدر وأطلق تنبيه اختبار على الخدمة.",
