    "Nenhum elemento corresponde ao seletor. Se o alerta aparecer na prévia, ajuste o seletor CSS.": "لا توجد عناصر تتطابق مع المحدد. إذا ظهر التنبيه في المعاينة، فاضبط محدد CSS.",
