    "Nenhuma sessão do SR salva. Se o YouTube exigir login, clique Conectar YouTube e entre na janela dedicada.": "لم يتم حفظ أي جلسات SR. إذا كان YouTube يتطلب تسجيل الدخول، فانقر فوق Connect YouTube وأدخل إلى النافذة المخصصة.",
