    "Não abre mais janela. Embed em branco travava na tela.": "لم يعد يفتح النافذة. تضمين فارغ عالق على الشاشة.",
    "Não achei músicas nessa playlist.": "لم أجد أي أغاني في قائمة التشغيل هذه.",
    "Não foi possível abrir a saída de áudio": "غير قادر على فتح إخراج الصوت",
    "Não foi possível acessar a sessão dedicada do YouTube.": "غير قادر على الوصول إلى جلسة YouTube المخصصة.",
    "Não foi possível gravar o TXT. Escolha outro arquivo e reconecte os chats.": "غير قادر على حفظ TXT. اختر ملفًا آخر وأعد توصيل الدردشات.",
    "Não foi possível importar a playlist. Verifique o link e a sessão YouTube.": "غير قادر على استيراد قائمة التشغيل. تحقق من رابط وجلسة YouTube.",
    "Não foi possível obter o áudio deste vídeo.": "غير قادر على الحصول على الصوت لهذا الفيديو.",
    "Não foi possível salvar. Reabra a Kaia para carregar o servidor do editor.": "غير قادر على الحفظ. أعد فتح Kaia لتحميل خادم الناشر.",
    "Não foi possível salvar:": "غير قادر على الحفظ:",
    "Não foi possível tocar o som. Escolha e salve a saída do leitor na aba Leitor.": "غير قادر على تشغيل الصوت. اختر واحفظ مخرجات القارئ في علامة تبويب القارئ.",
    "Não li a playlist:": "لم أقرأ قائمة التشغيل:",
    "Não li a playlist: {0}": "لم أقرأ قائمة التشغيل: {0}",
    "O SR está no mudo, independentemente do volume salvo.": "يتم كتم صوت SR بغض النظر عن وحدة التخزين المحفوظة.",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "ينشر Spotify المسار على شاشات HUDs؛ يستمر التشغيل في تطبيق Spotify. يتم تجديد التفويض والرموز تلقائيًا. يقوم SR بتشغيل الطلبات من YouTube، ولا يقوم بتنزيل الصوت من Spotify.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "تتضمن النسخة الاحتياطية الرسائل المستلمة من كافة الأنظمة الأساسية، بما في ذلك الألقاب المخفية بواسطة الدردشات المحظورة. يؤدي التلاشي إلى مسح الشاشة فقط.",
    "O campo da lista de mensagens não contém um array JSON.": "لا يحتوي حقل قائمة الرسائل على مصفوفة JSON.",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "استغرق الأمر {0} وقتًا طويلاً. تظل عناصر التحكم الأخرى متاحة؛ حاول ثانية.",
    "O decodificador não produziu áudio.": "لم يصدر جهاز فك التشفير صوتًا.",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "يستخدم جهاز القياس الصوت من الإخراج المحدد. قد تظهر أيضًا أصوات أخرى على نفس الجهاز. يحتفظ المحرر بالسمات وCSS وRGB والأشرطة من الحزمة الأصلية.",
    "O motor de áudio demorou para iniciar.": "كان محرك الصوت بطيئًا في البدء.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "لم يقم المتصفح بإصدار الجلسة المخصصة. أغلق نافذة YouTube هذه وحاول الاتصال مرة أخرى.",
    "O navegador recusou a sincronização da sessão.": "رفض المتصفح مزامنة الجلسة.",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "يعرض التراكب الثاني نفس البيانات مثل SR/Spotify. قم بتحرير المظهر هنا؛ يظل HUD القياسي متاحًا.",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "ملاحظة → أضف خط المتصفح. استخدم في البداية 800 × 320 وقم بالقص وفقًا للتخطيط. خلفية شفافة؛ لا حاجة لمفتاح كروما.",
    "Oculte mensagens e sons de nicks específicos": "إخفاء الرسائل والأصوات من ألقاب محددة",
    "Opacidade do fundo (%)": "عتامة الخلفية (%)",
    "Opcional: recomendado usar PKCE sem segredo": "اختياري: يوصى باستخدام PKCE بدون سر",
    "Operador": "المشغل",
    "Ordem manual salva; aleatório desativado.": "تم حفظ الطلب اليدوي؛ تعطيل عشوائي.",
    "Os avisos usam a saída salva no Leitor.": "تستخدم التحذيرات المخرجات المحفوظة في القارئ.",
    "PASS SCHMOOPIIE": "تمرير شموبي",
    "PRÉVIA AO VIVO ·": "معاينة مباشرة ·",
    "Padrão do Windows": "معيار ويندوز",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "للاستماع فقط عبر سماعة الرأس، اختر مخرجًا لم يتم التقاطه في OBS. لا تتحول القراءة إلى الإخراج القياسي إذا أصبح الجهاز المختار غير متاح. يتطلب Edge Voice الإنترنت.",
    "Parar": "توقف",
    "Parar e limpar todas as filas": "إيقاف ومسح كافة قوائم الانتظار",
    "Parar leitura": "توقف عن القراءة",
    "Pare a leitura atual antes de testar a voz.": "أوقف القراءة الحالية قبل اختبار الصوت.",
    "Pare a música antes de testar a saída do SR.": "أوقف الموسيقى قبل اختبار إخراج SR.",
    "Parece um Popen: poll/terminate/kill/wait.": "يبدو مثل بوبين: استطلاع/إنهاء/قتل/انتظار.",
    "Pausado": "متوقف مؤقتًا",
    "Pausar": "وقفة",
    "Pausar música": "إيقاف الموسيقى مؤقتًا",
    "Pedido pendente colocado novamente na fila.": "تم وضع الطلب المعلق مرة أخرى في قائمة الانتظار.",
    "Pedido:": "الترتيب:",
    "Pedidos !sr ativos.": "أوامر !sr النشطة.",
    "Pedidos !sr nome da música ou !sr link do YouTube, recebidos nos chats conectados, entram na fila. Ative abaixo para aceitar pedidos. Usuários bloqueados e mensagens históricas são ignorados.": "طلبات اسم الأغنية !sr أو رابط YouTube !sr، التي يتم تلقيها في الدردشات المتصلة، تدخل في قائمة الانتظار. قم بالتنشيط أدناه لقبول الطلبات. يتم تجاهل المستخدمين المحظورين والرسائل التاريخية.",
    "Pedidos SR ·": "أوامر ريال سعودي ·",
    "Pedidos das lives desativados.": "تم تعطيل الطلبات المباشرة.",
