    "Preservar as cores dos nomes de usuário": "الحفاظ على ألوان اسم المستخدم",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "خصوصية الصوت: يتم نقل أغاني SR دون تنزيل دائم. تستخدم الخطب ملفات مؤقتة، ويتم حذفها بعد الاستخدام وعند إغلاقها. يتم تنظيف بقايا المقاطعة عند بدء تشغيل محرك الصوت التالي. يتم الاحتفاظ بالأصوات التي اخترتها والنسخة الاحتياطية لـ TXT.",
    "Proteção de credenciais indisponível neste Windows.": "حماية بيانات الاعتماد غير متوفرة على نظام التشغيل Windows هذا.",
