    "Reação usa a energia e os picos do áudio do SR com saída explícita. Sem sinal medido (Spotify/player padrão), mantém apenas o ciclo RGB; não simula batidas.": "يستخدم رد الفعل الطاقة والارتفاعات في صوت SR مع إخراج واضح. بدون الإشارة المقاسة (Spotify/المشغل القياسي)، يحافظ فقط على دورة RGB؛ لا يحاكي يدق.",
