    "Salvar minhas credenciais": "احفظ بيانات الاعتماد الخاصة بي",
    "Salvar no overlay": "حفظ للتراكب",
    "Salvar temporizador": "حفظ الموقت",
    "Salvar widget e atualizar prévia": "حفظ القطعة ومعاينة التحديث",
    "Salve e ative a fonte antes de abrir a prévia.": "احفظ الخط وقم بتنشيطه قبل فتح المعاينة.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "احفظ باستخدام زر حفظ SR. تكون الطلبات التالية للتشغيل بعد المسار الحالي، وقبل الأغاني الموجودة في قائمة التشغيل. تنطبق الحدود على الإدخالات الجديدة ولا تقم بإزالة الأغاني المقبولة بالفعل. تستخدم أصوات الدردشة والمطالبات مخرجات القارئ؛ تستخدم الموسيقى إخراج SR. يجب أن يقوم OBS فقط بالتقاط مخرجات/عملية SR للحفاظ على خصوصية التحذيرات.",
    "Salve seu Client ID primeiro.": "احفظ معرف العميل الخاص بك أولاً.",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "أنقذ. يتم تحديث تراكب OBS خلال ثانيتين.",
