    "Saída da leitura": "قراءة الإخراج",
    "Saída da música": "إخراج الموسيقى",
    "Saída da soundbar": "إخراج مكبرات الصوت",
    "Saída de leitura indisponível; selecione novamente o dispositivo.": "إخراج القراءة غير متاح؛ حدد الجهاز مرة أخرى.",
    "Saída de áudio indisponível. Pedido preservado.": "إخراج الصوت غير متاح. النظام محفوظ.",
    "Saída padrão": "الإخراج القياسي",
    "Saída padrão do Windows": "ويندوز الإخراج القياسي",
    "Saída selecionada indisponível; áudio não enviado à saída padrão.": "الإخراج المحدد غير متاح؛ لم يتم إرسال الصوت إلى الإخراج القياسي.",
    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "تحديث مخرجات الصوت. حدد إخراج القراءة.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "مخرجات صوتية فريدة من نوعها. يستخدم SR وKaia أجهزة مختلفة. لا تستخدم ffmpeg -f Wasapi (العديد من إصدارات Windows لا تحتوي على هذا muxer). الافتراضي = ffplay. الجهاز المختار = ffmpeg PCM + جهاز الصوت.",
    "Scripts": "البرامج النصية",
    "Segredo protegido já salvo; vazio mantém o atual": "تم حفظ السر المحمي بالفعل؛ فارغة تبقى الحالية",
