    "Selecione a saída do leitor: os sons do chat usam essa saída privada.": "تحديد إخراج القارئ: تستخدم أصوات الدردشة هذا الإخراج الخاص.",
    "Selecione a saída e salve antes de ativar.": "حدد الإخراج وحفظه قبل التنشيط.",
    "Selecione e salve a saída de áudio do Leitor primeiro.": "حدد واحفظ إخراج صوت القارئ أولاً.",
