    "Seletores: #box, #lab, #tit, #who, .bar, #fill, #tempo. Não altera áudio ou reprodução.": "المحددات: #box، #lab، #tit، #who، .bar، #fill، #tempo. لا يغير الصوت أو التشغيل.",
    "Seletores: #feed, .message, .user, .message-text, .platform e [data-platform=\"kick\"]. O tempo das mensagens segue a aba Chat. O CSS é aplicado ao salvar.": "المحددات: #feed، .message، .user، .message-text، .platform و[data-platform = \"kick\"]. توقيت الرسائل يتبع علامة التبويب الدردشة. يتم تطبيق CSS على الحفظ.",
