    "Todos os idiomas": "جميع اللغات",
    "Tom de teste enviado à saída do SR. Confirme se você ouviu; este teste não usa YouTube nem os alertas.": "تم إرسال نغمة الاختبار إلى مخرج SR. أكد أنك سمعت؛ هذا الاختبار لا يستخدم يوتيوب أو التنبيهات.",
    "Toque uma música no Spotify. A faixa aparecerá aqui e nos HUDs. Não envie suas chaves ou tokens ao GitHub.": "تشغيل أغنية على سبوتيفي. سوف يظهر الشعار هنا وعلى شاشات HUDs. لا ترسل مفاتيحك أو رموزك المميزة إلى GitHub.",
    "Transcrição do chat": "نص الدردشة",
