    "Título (px)": "العنوان (بكسل)",
    "URL copiada.": "تم نسخ عنوان URL.",
    "URL copiada. No OBS, use Fonte de navegador e fundo transparente.": "تم نسخ عنوان URL. في OBS، استخدم خط المتصفح والخلفية الشفافة.",
    "URL da API JSON": "عنوان URL لواجهة برمجة تطبيقات JSON",
