    "URL do widget": "عنوان URL للقطعة",
    "URL privado do widget de alertas": "تنبيهات URL الخاص القطعة",
    "Um nick por linha": "لقب واحد في كل سطر",
    "Um nick por linha, ou separe por vírgulas. Aceita @ e ignora maiúsculas/minúsculas. O bloqueio é apenas neste overlay.": "لقب واحد في كل سطر، أو منفصلاً بفواصل. يقبل @ ويتجاهل الأحرف الكبيرة/الصغيرة. الحظر موجود فقط على هذا التراكب.",
    "Uma entrada por dispositivo físico. Prefere WASAPI do PortAudio.": "إدخال واحد لكل جهاز فعلي. تفضل WASAPI الخاص بـ PortAudio.",
    "Uma playlist já está sendo importada. Aguarde o resultado na tela.": "يتم بالفعل استيراد قائمة التشغيل. انتظر النتيجة على الشاشة.",
    "Usar este TXT": "استخدم هذا النص",
    "Use URL HTTP/HTTPS do widget, sem senha no endereço.": "استخدم عنوان URL HTTP/HTTPS الخاص بالأداة، بدون كلمة مرور في العنوان.",
    "Use até 1.000 nicks por lista de bloqueio.": "استخدم ما يصل إلى 1000 اسم مستعار لكل قائمة حظر.",
    "Use até 20 fontes de alertas.": "استخدم ما يصل إلى 20 مصدرًا للتنبيه.",
    "Use campos JSON separados por ponto, sem código.": "استخدم حقول JSON مفصولة بنقاط بدون رمز.",
    "Use um endpoint JSON público. Links de live e widgets HTML não são lidos automaticamente; cada serviço precisa permitir acesso às mensagens.": "استخدم نقطة نهاية JSON عامة. لا تتم قراءة الروابط المباشرة وعناصر واجهة مستخدم HTML تلقائيًا؛ يجب أن تسمح كل خدمة بالوصول إلى الرسائل.",
    "Use uma API HTTPS pública ou HTTP local, sem senha na URL.": "استخدم HTTPS عامًا أو HTTP API محليًا، بدون كلمة مرور في عنوان URL.",
    "Use ↑/↓ ou informe a posição para organizar manualmente. A ordem de cada lista é independente; ordenar desativa o aleatório.": "استخدم ↑/↓ أو أدخل الموضع للتنظيم يدويًا. ترتيب كل قائمة مستقل؛ ترتيب تعطيل عشوائي.",
    "Velocidade (%)": "السرعة (%)",
