    "Volume (%)": "مستوى الصوت (%)",
    "Voz": "صوت",
    "Vídeo privado, removido ou indisponível; escolha outra faixa.": "الفيديو خاص أو تمت إزالته أو غير متاح؛ اختر مسارًا آخر.",
    "Vídeo: Redirect URI": "فيديو: إعادة توجيه URI",
