    "Vídeos complementares em inglês podem mostrar uma interface antiga. Para a URL e o fluxo atuais, siga este tutorial e o guia oficial.": "قد تظهر مقاطع الفيديو الإضافية باللغة الإنجليزية واجهة قديمة. للحصول على عنوان URL والتدفق الحاليين، اتبع هذا البرنامج التعليمي والدليل الرسمي.",
