    "As fontes vêm do seu Windows. Em outro computador, fontes ausentes usam Segoe UI.": "फ़ॉन्ट आपके विंडोज़ से आते हैं। दूसरे कंप्यूटर पर, गुम फ़ॉन्ट Segoe UI का उपयोग करते हैं।",
    "As mensagens permanecem até limpar o painel ou atingir o limite de 300.": "संदेश तब तक बने रहते हैं जब तक आप पैनल साफ़ नहीं कर देते या 300 की सीमा तक नहीं पहुँच जाते।",
    "As novas mensagens entram em tempo real.": "नए संदेश वास्तविक समय में आते हैं।",
    "Atalho duplicado ou reservado para recuperar a janela.": "विंडो को पुनर्प्राप्त करने के लिए डुप्लिकेट या आरक्षित शॉर्टकट।",
