    "Pessoa de teste pediu Música de teste.": "परीक्षण व्यक्ति ने परीक्षण गीत का अनुरोध किया।",
    "Pessoa de teste seguiu o canal. Esta é a mensagem de teste do alerta.": "परीक्षण व्यक्ति ने चैनल का अनुसरण किया. यह चेतावनी परीक्षण संदेश है.",
