    "Posição de": "की स्थिति",
    "Preparando voz de {0} · {1} na fila · {2} descartadas pelo limite/filtro": "कतार में {0} · {1} की आवाजें तैयार करना · सीमा/फ़िल्टर द्वारा छोड़े गए {2}",
    "Preparando/reproduzindo aviso": "नोटिस तैयार करना/बजाना",
    "Preservar as cores dos nomes de usuário": "उपयोक्तानाम रंग सुरक्षित रखें",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "ऑडियो गोपनीयता: एसआर गाने स्थायी डाउनलोड के बिना प्रसारित होते हैं। भाषण में अस्थायी फ़ाइलों का उपयोग किया जाता है, उपयोग के बाद और बंद करते समय हटा दिया जाता है। किसी व्यवधान के अवशेष अगले ऑडियो इंजन स्टार्टअप पर साफ़ कर दिए जाते हैं। आपके द्वारा चुनी गई ध्वनियाँ और TXT बैकअप संरक्षित हैं।",
    "Proteção de credenciais indisponível neste Windows.": "इस विंडोज़ पर क्रेडेंशियल सुरक्षा उपलब्ध नहीं है।",
    "Prévia alterada · salve para aplicar no OBS.": "पूर्वावलोकन बदल गया · ओबीएस पर लागू करने के लिए सहेजें।",
    "Prévia ao vivo": "लाइव पूर्वावलोकन",
