    "RGB animado · ciclo de cores": "एनिमेटेड आरजीबी · रंग चक्र",
    "Reação usa a energia e os picos do áudio do SR com saída explícita. Sem sinal medido (Spotify/player padrão), mantém apenas o ciclo RGB; não simula batidas.": "प्रतिक्रिया स्पष्ट आउटपुट के साथ एसआर ऑडियो की ऊर्जा और स्पाइक्स का उपयोग करती है। मापे गए सिग्नल (Spotify/मानक प्लेयर) के बिना, केवल RGB चक्र को बनाए रखता है; धड़कनों का अनुकरण नहीं करता.",
    "Redirect URI — copie exatamente": "यूआरआई को रीडायरेक्ट करें - बिल्कुल कॉपी करें",
