    "Salvar widget e atualizar prévia": "विजेट सहेजें और पूर्वावलोकन अपडेट करें",
    "Salve e ative a fonte antes de abrir a prévia.": "पूर्वावलोकन खोलने से पहले फ़ॉन्ट को सहेजें और सक्रिय करें।",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "सेव एसआर बटन का उपयोग करके सेव करें। अनुरोध वर्तमान ट्रैक के बाद, प्लेलिस्ट में गाने से पहले चलने के लिए हैं। सीमाएँ नई प्रविष्टियों पर लागू होती हैं और पहले से स्वीकृत गीतों को नहीं हटाती हैं। चैट ध्वनियाँ और संकेत रीडर आउटपुट का उपयोग करते हैं; संगीत SR आउटपुट का उपयोग करता है। चेतावनियों को निजी रखने के लिए ओबीएस को केवल एसआर आउटपुट/प्रक्रिया को कैप्चर करना चाहिए।",
    "Salve seu Client ID primeiro.": "सबसे पहले अपना क्लाइंट आईडी सेव करें।",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "सहेजा गया. ओबीएस ओवरले दो सेकंड के भीतर अपडेट हो जाता है।",
    "Saída SR indisponível. Selecione novamente a saída da música.": "एसआर आउटपुट अनुपलब्ध. संगीत आउटपुट फिर से चुनें।",
    "Saída da leitura": "आउटपुट पढ़ना",
    "Saída da música": "संगीत आउटपुट",
    "Saída da soundbar": "साउंडबार आउटपुट",
    "Saída de leitura indisponível; selecione novamente o dispositivo.": "रीडिंग आउटपुट अनुपलब्ध; डिवाइस को दोबारा चुनें.",
    "Saída de áudio indisponível. Pedido preservado.": "ऑडियो आउटपुट अनुपलब्ध. आदेश सुरक्षित रखा गया.",
    "Saída padrão": "मानक आउटपुट",
    "Saída padrão do Windows": "विंडोज़ मानक आउटपुट",
    "Saída selecionada indisponível; áudio não enviado à saída padrão.": "चयनित आउटपुट अनुपलब्ध; ऑडियो मानक आउटपुट पर नहीं भेजा गया।",
    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "अद्यतन ऑडियो आउटपुट। रीडिंग आउटपुट का चयन करें.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "अनोखा ऑडियो आउटपुट. एसआर और कैया विभिन्न उपकरणों का उपयोग करते हैं। ffmpeg -f wasapi का उपयोग न करें (कई विंडोज़ बिल्ड में यह मक्सर नहीं है)। डिफ़ॉल्ट = एफएफप्ले। चुना गया डिवाइस = एफएफएमपीईजी पीसीएम + साउंडडिवाइस।",
    "Scripts": "लिपियाँ",
    "Segredo protegido já salvo; vazio mantém o atual": "संरक्षित रहस्य पहले ही सहेजा जा चुका है; खाली चालू रखता है",
    "Selecione a URL acima para copiar.": "कॉपी करने के लिए ऊपर दिए गए URL का चयन करें.",
