    "Selecione a saída e salve antes de ativar.": "आउटपुट का चयन करें और सक्रिय करने से पहले सहेजें।",
    "Selecione e salve a saída de áudio do Leitor primeiro.": "सबसे पहले रीडर का ऑडियो आउटपुट चुनें और सेव करें।",
    "Selecione e salve a saída de áudio primeiro.": "सबसे पहले ऑडियो आउटपुट चुनें और सेव करें।",
