    "Seletor CSS do texto": "टेक्स्ट सीएसएस चयनकर्ता",
    "Seletor do texto do alerta": "चेतावनी पाठ चयनकर्ता",
    "Seletores: #box, #lab, #tit, #who, .bar, #fill, #tempo. Não altera áudio ou reprodução.": "चयनकर्ता: #बॉक्स, #लैब, #तैसा, #कौन, .बार, #भरें, #टेम्पो। ऑडियो या प्लेबैक नहीं बदलता.",
    "Seletores: #feed, .message, .user, .message-text, .platform e [data-platform=\"kick\"]. O tempo das mensagens segue a aba Chat. O CSS é aplicado ao salvar.": "चयनकर्ता: #फीड, .मैसेज, .यूजर, .मैसेज-टेक्स्ट, .प्लेटफॉर्म और [डेटा-प्लेटफॉर्म='किक']। संदेशों का समय चैट टैब के अनुसार होता है। सीएसएस को सेव पर लागू किया जाता है।",
    "Sem login • Emotes nativos + 7TV, BTTV e FFZ públicos": "कोई लॉगिन नहीं • मूल भाव + सार्वजनिक 7TV, BTTV और FFZ",
