    "Spotify recusou a autorização (HTTP {0}). Confira Client ID, acesso do usuário e Redirect URI.": "Spotify ने प्राधिकरण अस्वीकार कर दिया (HTTP {0})। क्लाइंट आईडी, उपयोगकर्ता पहुंच और रीडायरेक्ट यूआरआई की जांच करें।",
