    "Tom de teste enviado à saída do SR. Confirme se você ouviu; este teste não usa YouTube nem os alertas.": "टेस्ट टोन एसआर आउटपुट को भेजा गया। पुष्टि करें कि आपने सुना; यह परीक्षण YouTube या अलर्ट का उपयोग नहीं करता है.",
    "Toque uma música no Spotify. A faixa aparecerá aqui e nos HUDs. Não envie suas chaves ou tokens ao GitHub.": "Spotify पर एक गाना बजाएं। बैनर यहां और एचयूडी पर दिखाई देगा। GitHub पर अपनी चाबियाँ या टोकन सबमिट न करें।",
