    "URL copiada.": "यूआरएल कॉपी किया गया.",
    "URL copiada. No OBS, use Fonte de navegador e fundo transparente.": "यूआरएल कॉपी किया गया. ओबीएस में, ब्राउज़र फ़ॉन्ट और पारदर्शी पृष्ठभूमि का उपयोग करें।",
