    "URL privado do widget de alertas": "अलर्ट विजेट निजी यूआरएल",
    "Um nick por linha": "प्रति पंक्ति एक उपनाम",
    "Um nick por linha, ou separe por vírgulas. Aceita @ e ignora maiúsculas/minúsculas. O bloqueio é apenas neste overlay.": "प्रति पंक्ति एक उपनाम, या अल्पविराम से अलग। @ स्वीकार करता है और ऊपरी/निचले मामले को अनदेखा करता है। अवरोध केवल इस ओवरले पर है.",
    "Uma entrada por dispositivo físico. Prefere WASAPI do PortAudio.": "प्रति भौतिक उपकरण एक प्रविष्टि. पोर्टऑडियो के WASAPI को प्राथमिकता दें।",
    "Uma playlist já está sendo importada. Aguarde o resultado na tela.": "एक प्लेलिस्ट पहले से ही आयात की जा रही है. स्क्रीन पर परिणाम की प्रतीक्षा करें।",
    "Usar este TXT": "इस TXT का प्रयोग करें",
    "Use URL HTTP/HTTPS do widget, sem senha no endereço.": "पते में पासवर्ड डाले बिना, विजेट के HTTP/HTTPS URL का उपयोग करें।",
    "Use até 1.000 nicks por lista de bloqueio.": "प्रति ब्लॉक सूची 1,000 उपनामों तक का उपयोग करें।",
    "Use até 20 fontes de alertas.": "20 अलर्ट स्रोतों तक का उपयोग करें।",
    "Use campos JSON separados por ponto, sem código.": "बिना कोड के डॉट-पृथक JSON फ़ील्ड का उपयोग करें।",
    "Use um endpoint JSON público. Links de live e widgets HTML não são lidos automaticamente; cada serviço precisa permitir acesso às mensagens.": "सार्वजनिक JSON समापन बिंदु का उपयोग करें. लाइव लिंक और HTML विजेट स्वचालित रूप से नहीं पढ़े जाते हैं; प्रत्येक सेवा को संदेशों तक पहुंच की अनुमति देनी होगी।",
    "Use uma API HTTPS pública ou HTTP local, sem senha na URL.": "यूआरएल में पासवर्ड के बिना सार्वजनिक HTTPS या स्थानीय HTTP एपीआई का उपयोग करें।",
    "Use ↑/↓ ou informe a posição para organizar manualmente. A ordem de cada lista é independente; ordenar desativa o aleatório.": "मैन्युअल रूप से व्यवस्थित करने के लिए ↑/↓ का उपयोग करें या स्थिति दर्ज करें। प्रत्येक सूची का क्रम स्वतंत्र है; आदेश यादृच्छिक अक्षम करता है।",
