    "Vídeo privado, removido ou indisponível; escolha outra faixa.": "वीडियो निजी, हटाया गया या अनुपलब्ध; दूसरा ट्रैक चुनें.",
    "Vídeo: Redirect URI": "वीडियो: यूआरआई को पुनर्निर्देशित करें",
