    "Vídeos complementares em inglês podem mostrar uma interface antiga. Para a URL e o fluxo atuais, siga este tutorial e o guia oficial.": "अंग्रेज़ी में पूरक वीडियो पुराना इंटरफ़ेस दिखा सकते हैं। वर्तमान यूआरएल और प्रवाह के लिए, इस ट्यूटोरियल और आधिकारिक गाइड का पालन करें।",
