    "YouTube exige login para este acesso. Na aba SR, clique Conectar YouTube, faça login na sessão dedicada e depois Testar acesso.": "इस एक्सेस के लिए YouTube को लॉगिन की आवश्यकता है। एसआर टैब में, कनेक्ट यूट्यूब पर क्लिक करें, समर्पित सत्र में लॉग इन करें और फिर एक्सेस का परीक्षण करें।",
    "YouTube limitou as requisições (HTTP 429). SR aguardando 10 minutos antes de tentar novamente.": "YouTube सीमित अनुरोध (HTTP 429)। पुनः प्रयास करने से पहले एसआर 10 मिनट प्रतीक्षा कर रहा है।",
