    ": alerta identificado; aguardando o fim para falar.": ": সতর্কতা চিহ্নিত করা হয়েছে; কথা বলার শেষের অপেক্ষায়।",
    ": falha ao carregar. Verifique o URL do widget.": ": লোড করতে ব্যর্থ হয়েছে৷ উইজেট URL চেক করুন.",
    ": monitorando texto HTML; dispare um alerta de teste no serviço.": ": HTML পাঠ্য পর্যবেক্ষণ; পরিষেবাতে একটি পরীক্ষার সতর্কতা ট্রিগার করুন।",
    ": não foi possível abrir a fonte.": ": উৎস খুলতে অক্ষম।",
    ": seletor CSS inválido. Corrija o campo do texto do alerta.": ": অবৈধ CSS নির্বাচক। সতর্কতা পাঠ্য ক্ষেত্রটি সংশোধন করুন।",
    ": texto do widget incorporado encontrado; aguardando alerta e término da mídia.": ": এমবেডেড উইজেট পাঠ্য পাওয়া গেছে; সতর্কতা এবং মিডিয়ার সমাপ্তির জন্য অপেক্ষা করছি।",
    "; tentando novamente…": "; আবার চেষ্টা...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"সম্পদ/পতাকা/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat — {0} সেশন ===",
    "A API precisa fornecer um ID único para cada mensagem.": "API-কে প্রতিটি বার্তার জন্য একটি অনন্য ID প্রদান করতে হবে।",
    "A API retornou uma resposta muito grande.": "API একটি খুব বড় প্রতিক্রিয়া ফিরে.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "পোর্ট 19348 ব্যস্ত। অন্য Spotify অনুমোদন বন্ধ করুন এবং আবার চেষ্টা করুন।",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "পূর্বরূপ প্রকৃত সঙ্গীত ব্যবহার করে. শুধুমাত্র সংরক্ষণ OBS উৎসে পরিবর্তনগুলি প্রয়োগ করে।",
    "A sessão YouTube demorou para responder.": "YouTube সেশনটি সাড়া দেওয়ার জন্য ধীর ছিল।",
    "API personalizada HTTP {0}": "কাস্টম HTTP API {0}",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Chrome/Edge-এ ডেডিকেটেড SR সেশন খুলুন এবং প্রয়োজনে YouTube-এ লগ ইন করুন। সেশন স্বয়ংক্রিয়ভাবে পুনরায় ব্যবহার করা হয় এবং সিঙ্ক্রোনাইজ করা হয়। ফোল্ডারে কুকিজ বা ক্যাশে অনুসন্ধান করার দরকার নেই। YouTube সীমাবদ্ধতার জন্য পুনরায় প্রমাণীকরণের প্রয়োজন হতে পারে বা কিছু ট্র্যাক প্রতিরোধ করতে পারে।",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Spotify ডেভেলপার ড্যাশবোর্ড খুলুন এবং আপনার অ্যাকাউন্ট দিয়ে লগ ইন করুন। ডেভেলপমেন্ট মোডে অ্যাপ্লিকেশানগুলির মালিক এবং প্যানেলে অনুমোদিত ব্যবহারকারীদের কাছ থেকে প্রিমিয়াম প্রয়োজন৷",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "প্লেয়ারটিকে তার নিজের নাম দিয়ে খুলুন: kaia_sr.exe বা kaia_voz.exe।",
    "Abrir HUD original": "আসল HUD খুলুন",
