    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "নামের কাছাকাছি ভিডিও খুঁজুন. লিঙ্ক = আইডি ব্যবহার করে। নাম = ytsearch অনুসন্ধান।",
    "Adicionar faixa à playlist de fundo": "ব্যাকগ্রাউন্ড প্লেলিস্টে ট্র্যাক যোগ করুন",
    "Adicionar pedido SR": "এসআর অর্ডার যোগ করুন",
    "Adicionar playlist": "প্লেলিস্ট যোগ করুন",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "ওবিএস-এ একটি ব্রাউজার উত্স হিসাবে URL যোগ করুন। Kaia Chat খোলা রাখুন, এমনকি জানালা লুকিয়ে রাখুন।",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "OBS-এ ব্যবহৃত উইজেট URL যোগ করুন। Streamlabs, StreamElements বা কাস্টমাইজড পরিষেবা। প্রতিটি ফন্টের নিজস্ব নাম/প্ল্যাটফর্ম রয়েছে। উইজেট নিঃশব্দ; স্বীকৃত পাঠ্য শুধুমাত্র রিডার আউটপুটে পড়া হয়। সতর্কতা উত্সগুলি সক্ষম করা স্বাভাবিক পড়া বন্ধ করে সতর্কতাগুলিও সক্ষম করে৷",
    "Aguardando pedido !sr": "!sr অর্ডারের জন্য অপেক্ষা করা হচ্ছে",
    "Alertas": "বিজ্ঞপ্তি",
    "Alertas para o streamer": "স্ট্রীমারের জন্য সতর্কতা",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "কিছু অস্থায়ী অডিও ব্যবহার করা হচ্ছে। পরবর্তী খোলার সময়ে পরিষ্কারের পুনরাবৃত্তি করা হবে।",
