    "Alta prioridade": "উচ্চ অগ্রাধিকার",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "উচ্চ অগ্রাধিকার সমস্ত বার্তা পড়ে এবং বর্তমান বক্তৃতা শেষ করার পরে সারির সামনে চলে যায়। সাধারণ এবং নিম্ন অগ্রাধিকারের পৃথক গণনা আছে। লাইভ অনুসরণ করার জন্য, পুরানো বার্তাগুলি অগ্রাধিকার সহ সর্বাধিক বিলম্ব অনুসারে বাতিল করা হয়। একটি পূর্ণ সারিতে, সর্বনিম্ন অগ্রাধিকার সহ সবচেয়ে বয়স্ক ব্যক্তিরা প্রথমে চলে যান। প্রতিটি বক্তৃতার পরে বিরতি যোগ না করে প্রস্তুতির শুরু থেকে বিরতি গণনা করা হয়। সংযোগে পুনরুদ্ধার করা ইতিহাস বলা হয় না।",
