    "Lê as novas mensagens dos canais conectados na aba Chat. Sem IA, sem responder na live. Os bloqueios gerais também valem para a voz.": "চ্যাট ট্যাবে সংযুক্ত চ্যানেল থেকে নতুন বার্তা পড়ুন। কোন এআই, কোন প্রতিক্রিয়া লাইভ. সাধারণ ব্লকগুলি ভয়েসের ক্ষেত্রেও প্রযোজ্য।",
