    "Nas configurações da aplicação, copie o Client ID para o campo desta aba. O fluxo PKCE de aplicativo desktop dispensa Client Secret; o campo opcional permite guardar o seu, se utilizado.": "অ্যাপ্লিকেশন সেটিংসে, এই ট্যাবের ক্ষেত্রে ক্লায়েন্ট আইডি কপি করুন। ডেস্কটপ অ্যাপ্লিকেশন PKCE প্রবাহের জন্য ক্লায়েন্ট সিক্রেট প্রয়োজন হয় না; ঐচ্ছিক ক্ষেত্রটি ব্যবহার করা হলে আপনি আপনার সংরক্ষণ করতে পারবেন।",
