    "Nenhum alerta recebido nesta sessão.": "এই সেশনে কোনো সতর্কতা পাওয়া যায়নি।",
    "Nenhum elemento corresponde ao seletor. Se o alerta aparecer na prévia, ajuste o seletor CSS.": "নির্বাচকের সাথে কোনো উপাদান মেলে না। প্রিভিউতে সতর্কতা দেখা দিলে, CSS সিলেক্টর অ্যাডজাস্ট করুন।",
