    "Nenhum pedido novo recebido nesta sessão.": "এই সেশনে কোনো নতুন অনুরোধ পাওয়া যায়নি।",
    "Nenhuma música em reprodução": "গান বাজছে না",
    "Nenhuma sessão do SR salva. Se o YouTube exigir login, clique Conectar YouTube e entre na janela dedicada.": "কোনো SR সেশন সেভ করা হয়নি। YouTube-এর লগইন করার প্রয়োজন হলে, YouTube কানেক্ট এ ক্লিক করুন এবং ডেডিকেটেড উইন্ডোতে প্রবেশ করুন।",
