    "Não abre mais janela. Embed em branco travava na tela.": "এটা আর জানালা খোলে না। ফাঁকা এম্বেড স্ক্রিনে আটকে আছে।",
    "Não achei músicas nessa playlist.": "আমি এই প্লেলিস্টে কোন গান খুঁজে পাইনি.",
    "Não foi possível abrir a saída de áudio": "অডিও আউটপুট খুলতে অক্ষম",
    "Não foi possível acessar a sessão dedicada do YouTube.": "ডেডিকেটেড YouTube সেশন অ্যাক্সেস করতে অক্ষম৷",
    "Não foi possível gravar o TXT. Escolha outro arquivo e reconecte os chats.": "TXT সংরক্ষণ করতে অক্ষম। অন্য ফাইল চয়ন করুন এবং চ্যাট পুনরায় সংযোগ করুন.",
    "Não foi possível importar a playlist. Verifique o link e a sessão YouTube.": "প্লেলিস্ট আমদানি করতে অক্ষম৷ YouTube লিঙ্ক এবং সেশন চেক করুন।",
    "Não foi possível obter o áudio deste vídeo.": "এই ভিডিওটির জন্য অডিও পেতে অক্ষম৷",
    "Não foi possível salvar. Reabra a Kaia para carregar o servidor do editor.": "সংরক্ষণ করতে অক্ষম। প্রকাশক সার্ভার লোড করতে Kaia পুনরায় খুলুন৷",
    "Não foi possível salvar:": "সংরক্ষণ করতে অক্ষম:",
    "Não foi possível tocar o som. Escolha e salve a saída do leitor na aba Leitor.": "শব্দ বাজাতে অক্ষম। রিডার ট্যাবে রিডার আউটপুট বেছে নিন এবং সংরক্ষণ করুন।",
    "Não li a playlist:": "আমি প্লেলিস্ট পড়িনি:",
    "Não li a playlist: {0}": "আমি প্লেলিস্টটি পড়িনি: {0}",
    "O SR está no mudo, independentemente do volume salvo.": "সংরক্ষিত ভলিউম নির্বিশেষে SR নিঃশব্দ করা হয়।",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify HUD-তে ট্র্যাক প্রকাশ করে; Spotify অ্যাপে প্লেব্যাক চলতে থাকে। অনুমোদন এবং টোকেন স্বয়ংক্রিয়ভাবে পুনর্নবীকরণ করা হয়. SR YouTube থেকে অনুরোধ চালায়, Spotify থেকে অডিও ডাউনলোড করে না।",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "ব্যাকআপে ব্লক করা চ্যাট দ্বারা লুকানো ডাকনাম সহ সমস্ত প্ল্যাটফর্ম থেকে প্রাপ্ত বার্তাগুলি অন্তর্ভুক্ত রয়েছে৷ ফেইড শুধুমাত্র পর্দা পরিষ্কার করে.",
    "O campo da lista de mensagens não contém um array JSON.": "বার্তা তালিকা ক্ষেত্রে একটি JSON অ্যারে নেই।",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "{0} কমান্ডটি খুব বেশি সময় নিয়েছে৷ অন্যান্য নিয়ন্ত্রণ উপলব্ধ থাকে; আবার চেষ্টা করুন",
    "O decodificador não produziu áudio.": "ডিকোডার অডিও তৈরি করেনি।",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "মিটার নির্বাচিত আউটপুট থেকে অডিও ব্যবহার করে। একই ডিভাইসে অন্যান্য শব্দও উপস্থিত হতে পারে। সম্পাদক মূল প্যাকেজ থেকে থিম, CSS, RGB এবং বার সংরক্ষণ করে।",
    "O motor de áudio demorou para iniciar.": "অডিও ইঞ্জিন শুরু হতে ধীর ছিল.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "ব্রাউজার ডেডিকেটেড সেশন প্রকাশ করেনি। এই YouTube উইন্ডোটি বন্ধ করুন এবং আবার সংযোগ করার চেষ্টা করুন৷",
    "O navegador recusou a sincronização da sessão.": "ব্রাউজারটি সেশনটি সিঙ্ক করতে অস্বীকার করেছে৷",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "দ্বিতীয় ওভারলে SR/Spotify এর মতো একই ডেটা দেখায়। এখানে চেহারা সম্পাদনা করুন; স্ট্যান্ডার্ড HUD উপলব্ধ থাকে।",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "দ্রষ্টব্য → ব্রাউজার ফন্ট যোগ করুন. প্রাথমিকভাবে 800 × 320 ব্যবহার করুন এবং লেআউট অনুযায়ী ক্রপ করুন। স্বচ্ছ পটভূমি; ক্রোমা কী প্রয়োজন নেই।",
    "Oculte mensagens e sons de nicks específicos": "নির্দিষ্ট ডাকনাম থেকে বার্তা এবং শব্দ লুকান",
    "Opacidade do fundo (%)": "পটভূমির অস্বচ্ছতা (%)",
    "Opcional: recomendado usar PKCE sem segredo": "ঐচ্ছিক: গোপন ছাড়া PKCE ব্যবহার করার জন্য সুপারিশ করা হয়",
