    "Padrão do Windows": "উইন্ডোজ স্ট্যান্ডার্ড",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "শুধুমাত্র হেডসেটে শোনার জন্য, একটি আউটপুট বেছে নিন যা OBS-এ ক্যাপচার করা হয় না। নির্বাচিত ডিভাইসটি অনুপলব্ধ হলে পঠন আদর্শ আউটপুটে স্যুইচ করে না। এজ ভয়েস ইন্টারনেট প্রয়োজন.",
