    "Pedidos !sr nome da música ou !sr link do YouTube, recebidos nos chats conectados, entram na fila. Ative abaixo para aceitar pedidos. Usuários bloqueados e mensagens históricas são ignorados.": "!sr গানের নাম বা !sr YouTube লিঙ্কের জন্য অনুরোধ, সংযুক্ত চ্যাটে প্রাপ্ত, সারিতে প্রবেশ করুন৷ অর্ডার গ্রহণ করতে নিচে সক্রিয় করুন. অবরুদ্ধ ব্যবহারকারী এবং ঐতিহাসিক বার্তা উপেক্ষা করা হয়.",
