    "Preservar as cores dos nomes de usuário": "ব্যবহারকারীর নাম রং সংরক্ষণ করুন",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "অডিও গোপনীয়তা: এসআর গান স্থায়ী ডাউনলোড ছাড়াই প্রেরণ করা হয়। বক্তৃতাগুলি অস্থায়ী ফাইলগুলি ব্যবহার করে, ব্যবহারের পরে এবং বন্ধ করার সময় মুছে ফেলা হয়। পরবর্তী অডিও ইঞ্জিন স্টার্টআপে একটি বাধার অবশিষ্টাংশ পরিষ্কার করা হয়। আপনার দ্বারা নির্বাচিত শব্দ এবং TXT ব্যাকআপ সংরক্ষিত হয়।",
    "Proteção de credenciais indisponível neste Windows.": "এই উইন্ডোজে ক্রেডেনশিয়াল সুরক্ষা অনুপলব্ধ৷",
    "Prévia alterada · salve para aplicar no OBS.": "প্রিভিউ পরিবর্তিত হয়েছে · OBS এ প্রয়োগ করতে সংরক্ষণ করুন।",
