    "Reação usa a energia e os picos do áudio do SR com saída explícita. Sem sinal medido (Spotify/player padrão), mantém apenas o ciclo RGB; não simula batidas.": "প্রতিক্রিয়া সুস্পষ্ট আউটপুট সহ SR অডিওর শক্তি এবং স্পাইক ব্যবহার করে। পরিমাপকৃত সংকেত ছাড়া (Spotify/স্ট্যান্ডার্ড প্লেয়ার), শুধুমাত্র RGB চক্র বজায় রাখে; বীট অনুকরণ করে না।",
