    "Salvar widget e atualizar prévia": "উইজেট সংরক্ষণ করুন এবং পূর্বরূপ আপডেট করুন",
    "Salve e ative a fonte antes de abrir a prévia.": "প্রাকদর্শন খোলার আগে ফন্ট সংরক্ষণ এবং সক্রিয় করুন.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "সেভ এসআর বোতাম ব্যবহার করে সংরক্ষণ করুন। অনুরোধগুলি বর্তমান ট্র্যাকের পরে প্লেলিস্টের গানগুলির আগে প্লে করার জন্য রয়েছে৷ সীমা নতুন এন্ট্রিগুলিতে প্রযোজ্য এবং ইতিমধ্যে গৃহীত গানগুলিকে সরিয়ে দেয় না। চ্যাট সাউন্ড এবং প্রম্পট রিডার আউটপুট ব্যবহার করে; সঙ্গীত এসআর আউটপুট ব্যবহার করে। সতর্কতাগুলি ব্যক্তিগত রাখতে OBS-এর শুধুমাত্র SR আউটপুট/প্রক্রিয়া ক্যাপচার করা উচিত।",
    "Salve seu Client ID primeiro.": "প্রথমে আপনার ক্লায়েন্ট আইডি সংরক্ষণ করুন।",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "সংরক্ষিত OBS ওভারলে দুই সেকেন্ডের মধ্যে আপডেট হয়।",
    "Saída SR indisponível. Selecione novamente a saída da música.": "SR আউটপুট অনুপলব্ধ৷ আবার সঙ্গীত আউটপুট নির্বাচন করুন.",
    "Saída da leitura": "আউটপুট পড়া",
