    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "অনন্য অডিও আউটপুট. SR এবং Kaia বিভিন্ন ডিভাইস ব্যবহার করে। ffmpeg -f wasapi ব্যবহার করবেন না (অনেক উইন্ডোজ বিল্ডে এই মুক্সার নেই)। ডিফল্ট = ffplay। নির্বাচিত ডিভাইস = ffmpeg PCM + সাউন্ড ডিভাইস।",
