    "YouTube acessível; áudio resolvido sem reproduzir.": "সাশ্রয়ী মূল্যের YouTube; অডিও বাজানো ছাড়া সমাধান.",
    "YouTube exige login para este acesso. Na aba SR, clique Conectar YouTube, faça login na sessão dedicada e depois Testar acesso.": "এই অ্যাক্সেসের জন্য YouTube-এর লগইন প্রয়োজন৷ এসআর ট্যাবে, কানেক্ট YouTube এ ক্লিক করুন, ডেডিকেটেড সেশনে লগ ইন করুন এবং তারপর এক্সেস পরীক্ষা করুন।",
    "YouTube limitou as requisições (HTTP 429). SR aguardando 10 minutos antes de tentar novamente.": "YouTube সীমিত অনুরোধ (HTTP 429)। আবার চেষ্টা করার আগে SR 10 মিনিট অপেক্ষা করছে।",
