    "; tentando novamente…": "; mencoba lagi...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"aset/bendera/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia Chat — sesi {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "API perlu memberikan ID unik untuk setiap pesan.",
    "A API retornou uma resposta muito grande.": "API memberikan respons yang sangat besar.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "Port 19348 sedang sibuk. Tutup otorisasi Spotify lainnya dan coba lagi.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "Pratinjau menggunakan musik sebenarnya. Hanya Simpan yang menerapkan perubahan pada sumber OBS.",
    "A sessão YouTube demorou para responder.": "Sesi YouTube lambat dalam merespons.",
    "API personalizada HTTP {0}": "API HTTP khusus {0}",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Buka sesi SR khusus di Chrome/Edge dan masuk ke YouTube jika perlu. Sesi ini secara otomatis digunakan kembali dan disinkronkan. Tidak perlu mencari cookie atau cache di folder. Pembatasan YouTube mungkin memerlukan autentikasi ulang atau mencegah beberapa trek.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Buka Dasbor Pengembang Spotify dan masuk dengan akun Anda. Aplikasi dalam Mode Pengembangan memerlukan Premium dari pemilik dan pengguna resmi di panel.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "Buka pemutar dengan namanya sendiri: kaia_sr.exe atau kaia_voz.exe.",
    "Abrir HUD original": "Buka HUD asli",
    "Abrir HUD padrão": "Buka HUD bawaan",
    "Abrir HUD personalizado": "Buka HUD khusus",
    "Abrir configurações / liberar cliques": "Buka Pengaturan / Klik Rilis",
    "Abrir overlay": "Buka hamparan",
    "Abrir painel Spotify": "Buka panel Spotify",
    "Abrir pop-up": "Buka munculan",
    "Abrir prévia desta fonte": "Buka pratinjau font ini",
    "Aceitar pedidos !sr das lives": "Terima pesanan !sr dari kehidupan",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "Temukan video yang paling dekat dengan namanya. Link = menggunakan id. Nama = pencarian ytsearch.",
    "Adicionar faixa à playlist de fundo": "Tambahkan trek ke daftar putar latar belakang",
    "Adicionar pedido SR": "Tambahkan pesanan SR",
    "Adicionar playlist": "Tambahkan daftar putar",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "Tambahkan URL sebagai Sumber Browser di OBS. Biarkan Kaia Chat tetap terbuka, meskipun jendelanya tersembunyi.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "Tambahkan URL widget yang digunakan di OBS. Streamlabs, StreamElements atau layanan yang disesuaikan. Setiap font memiliki nama/platformnya sendiri. Widget dinonaktifkan; teks yang dikenali hanya dibaca pada keluaran Pembaca. Mengaktifkan sumber peringatan juga mengaktifkan peringatan dengan pembacaan normal dimatikan.",
    "Aguardando pedido !sr": "Ditunggu pesanan !sr",
    "Alertas": "Notifikasi",
    "Alertas para o streamer": "Peringatan untuk streamer",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "Beberapa audio sementara sedang digunakan. Pembersihan akan diulangi pada pembukaan berikutnya.",
    "Alguém": "Seseorang",
    "Alt": "alternatif",
    "Alta prioridade": "Prioritas tinggi",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "Prioritas tinggi membaca semua pesan dan berpindah ke antrean depan setelah menyelesaikan pidato saat ini. Prioritas normal dan rendah memiliki hitungan terpisah. Untuk mengikuti siaran langsung, pesan-pesan lama dibuang sesuai dengan penundaan maksimum, termasuk pesan-pesan prioritas. Dalam antrian penuh, antrian terlama dengan prioritas terendah keluar terlebih dahulu. Istirahat dihitung dari awal persiapan, tanpa menambahkan jeda setelah setiap pidato. Riwayat yang diambil saat terhubung tidak diucapkan.",
