    "Nas configurações da aplicação, copie o Client ID para o campo desta aba. O fluxo PKCE de aplicativo desktop dispensa Client Secret; o campo opcional permite guardar o seu, se utilizado.": "Dalam pengaturan aplikasi, salin ID Klien ke bidang pada tab ini. Alur PKCE aplikasi desktop tidak memerlukan Rahasia Klien; bidang opsional memungkinkan Anda menyimpan milik Anda, jika digunakan.",
    "Navegador YouTube fechado.": "Peramban YouTube ditutup.",
