    "Negrito": "Berani",
    "Nenhum alerta recebido ainda. Salve a fonte e dispare um alerta de teste no serviço.": "Belum ada pemberitahuan yang diterima. Simpan sumbernya dan picu peringatan pengujian pada layanan.",
