    "Nenhuma sessão do SR salva. Se o YouTube exigir login, clique Conectar YouTube e entre na janela dedicada.": "Tidak ada sesi SR yang disimpan. Jika YouTube memerlukan login, klik Hubungkan YouTube dan masuk ke jendela khusus.",
