    "Não abre mais janela. Embed em branco travava na tela.": "Itu tidak lagi membuka jendela. Sematan Kosong tersangkut di layar.",
    "Não achei músicas nessa playlist.": "Saya tidak menemukan lagu apa pun di playlist ini.",
    "Não foi possível abrir a saída de áudio": "Tidak dapat membuka keluaran audio",
    "Não foi possível acessar a sessão dedicada do YouTube.": "Tidak dapat mengakses sesi YouTube khusus.",
    "Não foi possível gravar o TXT. Escolha outro arquivo e reconecte os chats.": "Tidak dapat menyimpan TXT. Pilih file lain dan sambungkan kembali obrolan.",
    "Não foi possível importar a playlist. Verifique o link e a sessão YouTube.": "Tidak dapat mengimpor daftar putar. Periksa tautan dan sesi YouTube.",
    "Não foi possível obter o áudio deste vídeo.": "Tidak dapat memperoleh audio untuk video ini.",
    "Não foi possível salvar. Reabra a Kaia para carregar o servidor do editor.": "Tidak dapat menyimpan. Buka kembali Kaia untuk memuat server penerbit.",
    "Não foi possível salvar:": "Tidak dapat menyimpan:",
    "Não foi possível tocar o som. Escolha e salve a saída do leitor na aba Leitor.": "Tidak dapat memutar suara. Pilih dan simpan keluaran pembaca di tab Pembaca.",
    "Não li a playlist:": "Saya tidak membaca playlistnya:",
    "Não li a playlist: {0}": "Saya tidak membaca playlist: {0}",
    "O SR está no mudo, independentemente do volume salvo.": "SR dibisukan terlepas dari volume yang disimpan.",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify memublikasikan lagu tersebut ke HUD; pemutaran berlanjut di aplikasi Spotify. Otorisasi dan token diperbarui secara otomatis. SR memutar permintaan dari YouTube, tidak mengunduh audio dari Spotify.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "Cadangan tersebut mencakup pesan yang diterima dari semua platform, termasuk nama panggilan yang disembunyikan oleh Obrolan yang diblokir. Memudar hanya menghilangkan layar.",
    "O campo da lista de mensagens não contém um array JSON.": "Bidang daftar pesan tidak berisi array JSON.",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "Perintah {0} memakan waktu terlalu lama. Kontrol lainnya tetap tersedia; coba lagi.",
    "O decodificador não produziu áudio.": "Decoder tidak menghasilkan audio.",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "Meteran menggunakan audio dari output yang dipilih. Suara lain pada perangkat yang sama mungkin juga muncul. Editor mempertahankan tema, CSS, RGB, dan bilah dari paket aslinya.",
    "O motor de áudio demorou para iniciar.": "Mesin audio lambat untuk dihidupkan.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "Browser tidak merilis sesi khusus. Tutup jendela YouTube ini dan coba Hubungkan lagi.",
    "O navegador recusou a sincronização da sessão.": "Browser menolak untuk menyinkronkan sesi tersebut.",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "Hamparan kedua menunjukkan data yang sama dengan SR/Spotify. Edit tampilannya di sini; HUD standar tetap tersedia.",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "CATATAN → tambahkan font browser. Awalnya gunakan 800×320 dan crop sesuai layout. Latar belakang transparan; Tidak perlu kunci kroma.",
    "Oculte mensagens e sons de nicks específicos": "Sembunyikan pesan dan suara dari nama panggilan tertentu",
    "Opacidade do fundo (%)": "Opasitas latar belakang (%)",
    "Opcional: recomendado usar PKCE sem segredo": "Opsional: disarankan menggunakan PKCE tanpa rahasia",
