    "Padrão do Windows": "Standar Windows",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "Untuk mendengarkan hanya di headset, pilih output yang tidak ditangkap di OBS. Pembacaan tidak beralih ke keluaran standar jika perangkat yang dipilih tidak tersedia. Edge Voice membutuhkan internet.",
