    "Pedidos !sr ativos.": "Pesanan !sr aktif.",
    "Pedidos !sr nome da música ou !sr link do YouTube, recebidos nos chats conectados, entram na fila. Ative abaixo para aceitar pedidos. Usuários bloqueados e mensagens históricas são ignorados.": "Permintaan nama lagu !sr atau link !sr YouTube, diterima di chat terhubung, masuk ke antrian. Aktifkan di bawah untuk menerima pesanan. Pengguna yang diblokir dan pesan historis diabaikan.",
