    "Preparando voz de {0} · {1} na fila · {2} descartadas pelo limite/filtro": "Mempersiapkan suara dari {0} · {1} dalam antrian · {2} dibuang berdasarkan batas/filter",
    "Preparando/reproduzindo aviso": "Mempersiapkan/memainkan pemberitahuan",
    "Preservar as cores dos nomes de usuário": "Pertahankan warna nama pengguna",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "Privasi audio: Lagu SR dikirimkan tanpa pengunduhan permanen. Pidato menggunakan file sementara, dihapus setelah digunakan dan saat ditutup. Sisa-sisa interupsi dibersihkan pada permulaan mesin audio berikutnya. Suara yang Anda pilih dan cadangan TXT dipertahankan.",
    "Proteção de credenciais indisponível neste Windows.": "Perlindungan kredensial tidak tersedia di Windows ini.",
