    "RGB animado · ciclo de cores": "RGB animasi · siklus warna",
    "Reação usa a energia e os picos do áudio do SR com saída explícita. Sem sinal medido (Spotify/player padrão), mantém apenas o ciclo RGB; não simula batidas.": "Reaksi menggunakan energi dan lonjakan audio SR dengan keluaran eksplisit. Tanpa sinyal terukur (Spotify/pemutar standar), hanya mempertahankan siklus RGB; tidak mensimulasikan ketukan.",
