    "Salve e ative a fonte antes de abrir a prévia.": "Simpan dan aktifkan font sebelum membuka pratinjau.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "Simpan menggunakan tombol Simpan SR. Permintaan selanjutnya diputar setelah trek saat ini, sebelum lagu dalam daftar putar. Batasan ini berlaku untuk entri baru dan tidak menghapus lagu yang sudah diterima. Suara dan perintah obrolan menggunakan keluaran Pembaca; musik menggunakan output SR. OBS seharusnya hanya menangkap keluaran/proses SR untuk menjaga privasi peringatan.",
    "Salve seu Client ID primeiro.": "Simpan ID Klien Anda terlebih dahulu.",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "Disimpan. Hamparan OBS diperbarui dalam dua detik.",
    "Saída SR indisponível. Selecione novamente a saída da música.": "Keluaran SR tidak tersedia. Pilih keluaran musik lagi.",
    "Saída da leitura": "Keluaran membaca",
    "Saída da música": "Keluaran musik",
    "Saída da soundbar": "Keluaran bilah suara",
    "Saída de leitura indisponível; selecione novamente o dispositivo.": "Hasil bacaan tidak tersedia; pilih perangkat lagi.",
    "Saída de áudio indisponível. Pedido preservado.": "Keluaran audio tidak tersedia. Pesanan terpelihara.",
    "Saída padrão": "Keluaran standar",
    "Saída padrão do Windows": "Keluaran standar Windows",
    "Saída selecionada indisponível; áudio não enviado à saída padrão.": "Keluaran yang dipilih tidak tersedia; audio tidak dikirim ke output standar.",
    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "Output audio yang diperbarui. Pilih keluaran bacaan.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "Output audio yang unik. SR dan Kaia menggunakan perangkat yang berbeda. Jangan gunakan ffmpeg -f wasapi (banyak build Windows yang tidak memiliki muxer ini). Default = putar ulang. Perangkat yang dipilih = ffmpeg PCM + perangkat suara.",
    "Scripts": "Skrip",
    "Segredo protegido já salvo; vazio mantém o atual": "Rahasia yang dilindungi sudah disimpan; kosong tetap terkini",
