    "Seletor do texto do alerta": "Pemilih teks peringatan",
    "Seletores: #box, #lab, #tit, #who, .bar, #fill, #tempo. Não altera áudio ou reprodução.": "Penyeleksi: #box, #lab, #tit, #who, .bar, #fill, #tempo. Tidak mengubah audio atau pemutaran.",
    "Seletores: #feed, .message, .user, .message-text, .platform e [data-platform=\"kick\"]. O tempo das mensagens segue a aba Chat. O CSS é aplicado ao salvar.": "Pemilih: #feed, .message, .user, .message-text, .platform dan [data-platform=\"kick\"]. Waktu pesan mengikuti tab Obrolan. CSS diterapkan saat menyimpan.",
