    "Nas configurações da aplicação, copie o Client ID para o campo desta aba. O fluxo PKCE de aplicativo desktop dispensa Client Secret; o campo opcional permite guardar o seu, se utilizado.": "アプリケーション設定で、クライアント ID をこのタブのフィールドにコピーします。デスクトップ アプリケーションの PKCE フローにはクライアント シークレットは必要ありません。オプションのフィールドを使用すると、フィールドを保存できます。",
    "Navegador YouTube fechado.": "YouTube ブラウザが閉じられました。",
