    "Negrito": "太字",
    "Nenhum alerta recebido ainda. Salve a fonte e dispare um alerta de teste no serviço.": "まだアラートを受信していません。ソースを保存し、サービスでテスト アラートをトリガーします。",
    "Nenhum alerta recebido nesta sessão.": "このセッションではアラートを受信しませんでした。",
    "Nenhum elemento corresponde ao seletor. Se o alerta aparecer na prévia, ajuste o seletor CSS.": "セレクターに一致する要素はありません。プレビューにアラートが表示される場合は、CSS セレクターを調整します。",
    "Nenhum pedido com falha para tentar novamente.": "失敗した再試行リクエストはありません。",
    "Nenhum pedido novo recebido nesta sessão.": "このセッションでは新しいリクエストは受信されませんでした。",
    "Nenhuma música em reprodução": "音楽が再生されていません",
    "Nenhuma sessão do SR salva. Se o YouTube exigir login, clique Conectar YouTube e entre na janela dedicada.": "SR セッションは保存されませんでした。 YouTube にログインが必要な場合は、「YouTube に接続」をクリックして専用ウィンドウに入ります。",
