    "Novo provedor Kick ainda não suportado": "新しい Kick プロバイダーはまだサポートされていません",
    "Não abre mais janela. Embed em branco travava na tela.": "もう窓は開かなくなりました。空白の埋め込みが画面上でスタックします。",
    "Não achei músicas nessa playlist.": "このプレイリストには曲が見つかりませんでした。",
