    "Não foi possível gravar o TXT. Escolha outro arquivo e reconecte os chats.": "TXTを保存できません。別のファイルを選択してチャットを再接続します。",
    "Não foi possível importar a playlist. Verifique o link e a sessão YouTube.": "プレイリストをインポートできません。 YouTube のリンクとセッションを確認してください。",
