    "Não foi possível salvar:": "保存できません:",
    "Não foi possível tocar o som. Escolha e salve a saída do leitor na aba Leitor.": "音声を再生できません。 [リーダー] タブでリーダー出力を選択して保存します。",
    "Não li a playlist:": "プレイリストを読んでいません:",
    "Não li a playlist: {0}": "プレイリストを読みませんでした: {0}",
    "O SR está no mudo, independentemente do volume salvo.": "SR は保存された音量に関係なくミュートされます。",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify はトラックを HUD に公開します。 Spotify アプリでは再生が続行されます。認可とトークンは自動的に更新されます。 SR は YouTube からのリクエストを再生しますが、Spotify からオーディオをダウンロードしません。",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "バックアップには、ブロックされたチャットによって隠されたニックネームを含む、すべてのプラットフォームから受信したメッセージが含まれます。フェードは画面をクリアするだけです。",
    "O campo da lista de mensagens não contém um array JSON.": "メッセージ リスト フィールドには JSON 配列が含まれません。",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "{0} コマンドに時間がかかりすぎました。他のコントロールは引き続き使用できます。もう一度やり直してください。",
    "O decodificador não produziu áudio.": "デコーダは音声を生成しませんでした。",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "メーターは、選択された出力からのオーディオを使用します。同じデバイス上の他のサウンドも表示される場合があります。エディターは、元のパッケージのテーマ、CSS、RGB、およびバーを保持します。",
    "O motor de áudio demorou para iniciar.": "オーディオ エンジンの起動が遅かった。",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "ブラウザは専用セッションを解放しませんでした。この YouTube ウィンドウを閉じて、もう一度接続してみてください。",
    "O navegador recusou a sincronização da sessão.": "ブラウザがセッションの同期を拒否しました。",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "2 番目のオーバーレイには SR/Spotify と同じデータが表示されます。ここで外観を編集します。標準の HUD は引き続き利用可能です。",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "注→ブラウザのフォントを追加します。最初は800×320を使用し、レイアウトに応じてトリミングします。透明な背景。クロマキーも必要ありません。",
    "Oculte mensagens e sons de nicks específicos": "特定のニックネームからのメッセージとサウンドを非表示にする",
    "Opacidade do fundo (%)": "背景の不透明度 (%)",
    "Opcional: recomendado usar PKCE sem segredo": "オプション: シークレットなしで PKCE を使用することを推奨します",
    "Operador": "オペレーター",
    "Ordem manual salva; aleatório desativado.": "手動注文が保存されました。ランダム無効。",
