    "PRÉVIA AO VIVO ·": "ライブプレビュー ·",
    "Padrão do Windows": "Windows標準",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "ヘッドセットのみで聴くには、OBS でキャプチャされない出力を選択します。選択したデバイスが使用できなくなった場合、読み取りは標準出力に切り替わりません。 Edge Voice にはインターネットが必要です。",
    "Parar": "停止",
    "Parar e limpar todas as filas": "すべてのキューを停止してクリアする",
    "Parar leitura": "読むのをやめる",
    "Pare a leitura atual antes de testar a voz.": "音声をテストする前に、現在の読み上げを停止してください。",
    "Pare a música antes de testar a saída do SR.": "SR 出力をテストする前に音楽を停止してください。",
