    "Pedidos !sr ativos.": "アクティブな !sr オーダー。",
    "Pedidos !sr nome da música ou !sr link do YouTube, recebidos nos chats conectados, entram na fila. Ative abaixo para aceitar pedidos. Usuários bloqueados e mensagens históricas são ignorados.": "接続されたチャットで受信した !sr 曲名または !sr YouTube リンクのリクエストはキューに入ります。注文を受け入れるには、以下をアクティブにしてください。ブロックされたユーザーと履歴メッセージは無視されます。",
