    "Posição de": "の位置",
    "Preparando voz de {0} · {1} na fila · {2} descartadas pelo limite/filtro": "{0} の音声を準備しています · キュー内の {1} · 制限/フィルターによって破棄された {2}",
    "Preparando/reproduzindo aviso": "準備中・プレイ中のお知らせ",
    "Preservar as cores dos nomes de usuário": "ユーザー名の色を保持する",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "オーディオのプライバシー: SR ソングは永久ダウンロードせずに送信されます。スピーチでは一時ファイルが使用され、使用後および終了時に削除されます。割り込みの残りは、次回のオーディオ エンジンの起動時にクリーンアップされます。あなたが選択したサウンドとTXTバックアップは保存されます。",
    "Proteção de credenciais indisponível neste Windows.": "この Windows では資格情報の保護は利用できません。",
