    "Reação usa a energia e os picos do áudio do SR com saída explícita. Sem sinal medido (Spotify/player padrão), mantém apenas o ciclo RGB; não simula batidas.": "リアクションは、SR オーディオのエネルギーとスパイクを明示的な出力で使用します。測定信号 (Spotify/標準プレーヤー) がない場合は、RGB サイクルのみを維持します。ビートをシミュレートしません。",
