    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "[SR を保存] ボタンを使用して保存します。リクエストは、現在のトラックの後、プレイリスト内の曲の前に再生されます。この制限は新しいエントリーに適用され、すでに受け入れられた曲は削除されません。チャットのサウンドとプロンプトはリーダー出力を使用します。音楽は SR 出力を使用します。 OBS は、警告をプライベートに保つために SR 出力/プロセスのみをキャプチャする必要があります。",
    "Salve seu Client ID primeiro.": "まずクライアント ID を保存してください。",
