    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "オーディオ出力を更新しました。読み取り出力を選択します。",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "ユニークなオーディオ出力。 SR と Kaia は異なるデバイスを使用しています。 ffmpeg -f wasapi は使用しないでください (多くの Windows ビルドにはこのマルチプレクサがありません)。デフォルト = ffplay。選択したデバイス = ffmpeg PCM + サウンドデバイス。",
