    "=== Kaia Chat — sessão {0} ===": "=== Kaia 채팅 — 세션 {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "API는 각 메시지에 고유 ID를 제공해야 합니다.",
    "A API retornou uma resposta muito grande.": "API가 매우 큰 응답을 반환했습니다.",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "포트 19348이 사용 중입니다. 다른 Spotify 인증을 종료하고 다시 시도하세요.",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "미리보기에는 실제 음악이 사용됩니다. 저장만 OBS 소스에 변경 사항을 적용합니다.",
    "A sessão YouTube demorou para responder.": "YouTube 세션의 응답이 느렸습니다.",
    "API personalizada HTTP {0}": "맞춤 HTTP API {0}",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "Chrome/Edge에서 전용 SR 세션을 열고 필요한 경우 YouTube에 로그인하세요. 세션은 자동으로 재사용되고 동기화됩니다. 폴더에서 쿠키나 캐시를 검색할 필요가 없습니다. YouTube 제한사항으로 인해 재인증이 필요하거나 일부 트랙이 차단될 수 있습니다.",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "Spotify 개발자 대시보드를 열고 계정으로 로그인하세요. 개발 모드의 애플리케이션에는 패널의 소유자 및 승인된 사용자의 프리미엄이 필요합니다.",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "kaia_sr.exe 또는 kaia_voz.exe라는 고유 이름으로 플레이어를 엽니다.",
    "Abrir HUD original": "원본 HUD 열기",
