    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "이름에 가장 가까운 비디오를 찾으십시오. 링크 = 해당 아이디를 사용합니다. 이름 = ytsearch 검색.",
    "Adicionar faixa à playlist de fundo": "배경 재생 목록에 트랙 추가",
