    "Adicionar playlist": "재생목록 추가",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "OBS에 브라우저 소스로 URL을 추가하세요. 창이 숨겨져 있어도 Kaia Chat을 열어두세요.",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "OBS에서 사용되는 위젯 URL을 추가합니다. Streamlabs, StreamElements 또는 맞춤형 서비스. 각 글꼴에는 고유한 이름/플랫폼이 있습니다. 위젯이 음소거되었습니다. 인식된 텍스트는 Reader 출력에서만 읽혀집니다. 경고 소스를 활성화하면 일반 읽기가 꺼진 상태에서도 경고가 활성화됩니다.",
    "Aguardando pedido !sr": "주문을 기다리고 있습니다!sr",
    "Alertas": "알림",
    "Alertas para o streamer": "스트리머를 위한 알림",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "일부 임시 오디오가 사용 중입니다. 다음 개점 시 청소가 반복됩니다.",
    "Alguém": "누군가",
    "Alt": "Alt",
    "Alta prioridade": "높은 우선순위",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "높은 우선순위는 모든 메시지를 읽고 현재 음성을 마친 후 대기열의 맨 앞으로 이동합니다. 보통 및 낮은 우선순위에는 별도의 개수가 있습니다. 라이브를 따르기 위해 우선 순위 메시지를 포함하여 최대 지연 시간에 따라 오래된 메시지가 삭제됩니다. 전체 대기열에서는 우선 순위가 가장 낮은 가장 오래된 대기열이 먼저 떠납니다. 휴식 시간은 각 연설 후에 일시 중지를 추가하지 않고 준비 시작부터 계산됩니다. 연결 시 검색된 기록은 음성으로 전달되지 않습니다.",
