    "Clique Salvar minhas credenciais, depois Conectar Spotify. Autorize no navegador oficial e volte ao Kaia Chat.": "내 자격 증명 저장을 클릭한 다음 Spotify 연결을 클릭합니다. 공식 브라우저에서 승인하고 Kaia Chat으로 돌아갑니다.",
