    "Compacto": "콤팩트",
    "Compatível com texto HTML acessível. Conteúdo em canvas, imagem/vídeo ou iframe de outro domínio pode não ser legível. Não é OCR e não identifica eventos ausentes do widget. Use o botão de teste do seu serviço após salvar. Não compartilhe seus URLs privados.": "접근 가능한 HTML 텍스트를 지원합니다. 다른 도메인의 캔버스, 이미지/비디오 또는 iframe 콘텐츠를 읽지 못할 수도 있습니다. 이는 OCR이 아니며 누락된 위젯 이벤트를 식별하지 않습니다. 저장 후 서비스 테스트 버튼을 사용하세요. 비공개 URL을 공유하지 마세요.",
