    "Nas configurações da aplicação, copie o Client ID para o campo desta aba. O fluxo PKCE de aplicativo desktop dispensa Client Secret; o campo opcional permite guardar o seu, se utilizado.": "애플리케이션 설정에서 클라이언트 ID를 이 탭의 필드에 복사하세요. 데스크톱 애플리케이션 PKCE 흐름에는 클라이언트 비밀번호가 필요하지 않습니다. 선택 필드를 사용하면 해당 필드를 저장할 수 있습니다.",
    "Navegador YouTube fechado.": "YouTube 브라우저가 닫혔습니다.",
    "Navegador dedicado aberto. Faça login no YouTube e depois teste o acesso.": "전용 브라우저를 엽니다. YouTube에 로그인한 후 액세스를 테스트해 보세요.",
    "Negrito": "굵게",
    "Nenhum alerta recebido ainda. Salve a fonte e dispare um alerta de teste no serviço.": "아직 수신된 알림이 없습니다. 소스를 저장하고 서비스에 대한 테스트 경고를 트리거합니다.",
    "Nenhum alerta recebido nesta sessão.": "이 세션에서는 알림이 수신되지 않았습니다.",
    "Nenhum elemento corresponde ao seletor. Se o alerta aparecer na prévia, ajuste o seletor CSS.": "선택기와 일치하는 요소가 없습니다. 미리보기에 경고가 나타나면 CSS 선택기를 조정하세요.",
