    "Nenhuma música em reprodução": "음악이 재생되지 않음",
    "Nenhuma sessão do SR salva. Se o YouTube exigir login, clique Conectar YouTube e entre na janela dedicada.": "저장된 SR 세션이 없습니다. YouTube에서 로그인이 필요한 경우 YouTube 연결을 클릭하고 전용 창으로 들어갑니다.",
