    "Novo provedor Kick ainda não suportado": "새로운 Kick 제공자는 아직 지원되지 않습니다.",
    "Não abre mais janela. Embed em branco travava na tela.": "더 이상 창이 열리지 않습니다. 빈 Embed가 화면에 멈췄습니다.",
    "Não achei músicas nessa playlist.": "이 재생목록에서 노래를 찾을 수 없습니다.",
    "Não foi possível abrir a saída de áudio": "오디오 출력을 열 수 없습니다.",
    "Não foi possível acessar a sessão dedicada do YouTube.": "전용 YouTube 세션에 액세스할 수 없습니다.",
    "Não foi possível gravar o TXT. Escolha outro arquivo e reconecte os chats.": "TXT를 저장할 수 없습니다. 다른 파일을 선택하고 채팅을 다시 연결하세요.",
    "Não foi possível importar a playlist. Verifique o link e a sessão YouTube.": "재생목록을 가져올 수 없습니다. YouTube 링크와 세션을 확인하세요.",
    "Não foi possível obter o áudio deste vídeo.": "이 동영상에 대한 오디오를 가져올 수 없습니다.",
    "Não foi possível salvar. Reabra a Kaia para carregar o servidor do editor.": "저장할 수 없습니다. Kaia를 다시 열어 게시자 서버를 로드합니다.",
    "Não foi possível salvar:": "저장할 수 없음:",
    "Não foi possível tocar o som. Escolha e salve a saída do leitor na aba Leitor.": "사운드를 재생할 수 없습니다. 리더 탭에서 리더 출력을 선택하고 저장합니다.",
    "Não li a playlist:": "재생목록을 읽지 않았습니다.",
    "Não li a playlist: {0}": "재생목록을 읽지 않았습니다: {0}",
    "O SR está no mudo, independentemente do volume salvo.": "저장된 볼륨에 관계없이 SR이 음소거됩니다.",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify는 트랙을 HUD에 게시합니다. Spotify 앱에서 재생이 계속됩니다. 승인 및 토큰은 자동으로 갱신됩니다. SR은 YouTube의 요청을 재생하지만 Spotify에서 오디오를 다운로드하지 않습니다.",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "백업에는 차단된 채팅으로 인해 숨겨진 닉네임을 포함하여 모든 플랫폼에서 받은 메시지가 포함됩니다. 페이드는 화면만 지웁니다.",
    "O campo da lista de mensagens não contém um array JSON.": "메시지 목록 필드에 JSON 배열이 포함되어 있지 않습니다.",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "{0} 명령이 너무 오래 걸렸습니다. 다른 컨트롤은 계속 사용할 수 있습니다. 다시 시도해 보세요.",
    "O decodificador não produziu áudio.": "디코더에서 오디오가 생성되지 않았습니다.",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "미터는 선택한 출력의 오디오를 사용합니다. 동일한 장치에서 다른 소리가 나타날 수도 있습니다. 편집기는 원본 패키지의 테마, CSS, RGB 및 막대를 유지합니다.",
    "O motor de áudio demorou para iniciar.": "오디오 엔진의 시작 속도가 느렸습니다.",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "브라우저가 전용 세션을 해제하지 않았습니다. 이 YouTube 창을 닫고 다시 연결해 보세요.",
    "O navegador recusou a sincronização da sessão.": "브라우저가 세션 동기화를 거부했습니다.",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "두 번째 오버레이에는 SR/Spotify와 동일한 데이터가 표시됩니다. 여기에서 모양을 편집하세요. 표준 HUD는 계속 사용할 수 있습니다.",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "참고 → 브라우저 글꼴을 추가하세요. 처음에는 800 × 320을 사용하고 레이아웃에 따라 자릅니다. 투명한 배경; 크로마키가 필요하지 않습니다.",
    "Oculte mensagens e sons de nicks específicos": "특정 닉네임의 메시지와 소리 숨기기",
    "Opacidade do fundo (%)": "배경 불투명도(%)",
    "Opcional: recomendado usar PKCE sem segredo": "선택 사항: 비밀 정보 없이 PKCE를 사용하는 것이 좋습니다.",
    "Operador": "운영자",
    "Ordem manual salva; aleatório desativado.": "수동 주문이 저장되었습니다. 무작위 비활성화.",
    "Os avisos usam a saída salva no Leitor.": "경고는 Reader에 저장된 출력을 사용합니다.",
    "PASS SCHMOOPIIE": "슈무피에 패스",
    "PRÉVIA AO VIVO ·": "실시간 미리보기 ·",
    "Padrão do Windows": "윈도우 표준",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "헤드셋에서만 들으려면 OBS에서 캡처되지 않는 출력을 선택하세요. 선택한 장치를 사용할 수 없게 되면 읽기가 표준 출력으로 전환되지 않습니다. Edge Voice에는 인터넷이 필요합니다.",
    "Parar": "중지",
    "Parar e limpar todas as filas": "모든 대기열을 중지하고 지우십시오.",
    "Parar leitura": "읽기 중지",
    "Pare a leitura atual antes de testar a voz.": "음성을 테스트하기 전에 현재 읽기를 중지하십시오.",
