    "Pausar música": "음악 일시중지",
    "Pedido pendente colocado novamente na fila.": "보류 중인 주문이 대기열에 다시 배치되었습니다.",
    "Pedido:": "주문:",
    "Pedidos !sr ativos.": "활성!sr 주문.",
    "Pedidos !sr nome da música ou !sr link do YouTube, recebidos nos chats conectados, entram na fila. Ative abaixo para aceitar pedidos. Usuários bloqueados e mensagens históricas são ignorados.": "연결된 채팅에서 받은 !sr 노래 이름 또는 !sr YouTube 링크 요청이 대기열에 들어갑니다. 주문을 수락하려면 아래를 활성화하세요. 차단된 사용자 및 기록 메시지는 무시됩니다.",
    "Pedidos SR ·": "SR 주문 ·",
    "Pedidos das lives desativados.": "실시간 요청이 비활성화되었습니다.",
    "Pega URL de áudio pra tocar. Não baixa arquivo.": "재생할 오디오 URL을 가져옵니다. 파일을 다운로드하지 않습니다.",
