    "Playlist de fundo: {0} faixas. !sr do chat fura a fila.": "배경 재생목록: {0} 트랙. 채팅의 !sr이 대기열을 뛰어넘습니다.",
    "Playlist do YouTube": "유튜브 재생목록",
    "Playlist só o admin cola no player do SR (botão playlist).": "관리자만이 재생 목록을 SR 플레이어(재생 목록 버튼)에 붙여넣을 수 있습니다.",
    "Pode voltar ao Kaia Chat.": "카이아 채팅으로 돌아갈 수 있습니다.",
