    "Posição da música": "음악 위치",
    "Posição da música na aba Chat": "채팅 탭의 음악 위치",
    "Posição de": "위치",
    "Preparando voz de {0} · {1} na fila · {2} descartadas pelo limite/filtro": "{0}의 음성 준비 중 · 대기열에 있는 {1} · 한도/필터에 의해 삭제된 {2}",
    "Preparando/reproduzindo aviso": "공지사항 준비/연주 중",
    "Preservar as cores dos nomes de usuário": "사용자 이름 색상 유지",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "오디오 개인 정보 보호: SR 노래는 영구 다운로드 없이 전송됩니다. 연설은 임시 파일을 사용하며 사용 후 및 종료 시 삭제됩니다. 인터럽트의 남은 부분은 다음 오디오 엔진 시작 시 정리됩니다. 귀하가 선택한 사운드와 TXT 백업이 보존됩니다.",
    "Proteção de credenciais indisponível neste Windows.": "이 Windows에서는 자격 증명 보호를 사용할 수 없습니다.",
    "Prévia alterada · salve para aplicar no OBS.": "미리보기가 변경되었습니다. OBS에 적용하려면 저장하세요.",
    "Prévia ao vivo": "실시간 미리보기",
    "Prévia do HUD SR": "HUD SR 미리보기",
    "Prévia do overlay": "오버레이 미리보기",
    "Prévia do widget": "위젯 미리보기",
    "Próxima": "다음",
    "Próxima música": "다음 노래",
    "Quantidade de barras": "바의 수량",
    "RGB + reação ao áudio real do SR": "실제 SR 오디오에 대한 RGB + 반응",
    "RGB animado · ciclo de cores": "애니메이션 RGB · 색상주기",
    "Reação usa a energia e os picos do áudio do SR com saída explícita. Sem sinal medido (Spotify/player padrão), mantém apenas o ciclo RGB; não simula batidas.": "Reaction은 명시적 출력과 함께 SR 오디오의 에너지와 스파이크를 사용합니다. 측정된 신호(Spotify/표준 플레이어)가 없으면 RGB 주기만 유지합니다. 비트를 시뮬레이션하지 않습니다.",
    "Redirect URI — copie exatamente": "리디렉션 URI — 정확하게 복사",
    "Remover": "제거",
