    "Retro · arcade": "레트로 · 아케이드",
    "Revise os URLs e seletores das fontes de alertas.": "경고 소스 URL 및 선택기를 검토하세요.",
    "Runtime de áudio ausente. Use o ZIP completo ou prepare .runtime.": "오디오 런타임이 누락되었습니다. 전체 ZIP을 사용하거나 .runtime을 준비하세요.",
