    "Salvar no overlay": "오버레이에 저장",
    "Salvar temporizador": "타이머 저장",
    "Salvar widget e atualizar prévia": "위젯 저장 및 미리보기 업데이트",
    "Salve e ative a fonte antes de abrir a prévia.": "미리보기를 열기 전에 글꼴을 저장하고 활성화하세요.",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "SR 저장 버튼을 사용하여 저장합니다. 요청은 현재 트랙 다음, 재생 목록의 노래 이전에 재생됩니다. 새 항목에는 제한이 적용되며 이미 승인된 노래는 제거되지 않습니다. 채팅 사운드 및 프롬프트는 리더 출력을 사용합니다. 음악은 SR 출력을 사용합니다. OBS는 경고를 비공개로 유지하기 위해 SR 출력/프로세스만 캡처해야 합니다.",
    "Salve seu Client ID primeiro.": "먼저 클라이언트 ID를 저장하세요.",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "저장되었습니다. OBS 오버레이는 2초 내에 업데이트됩니다.",
    "Saída SR indisponível. Selecione novamente a saída da música.": "SR 출력을 사용할 수 없습니다. 음악 출력을 다시 선택하세요.",
    "Saída da leitura": "출력 읽기",
    "Saída da música": "음악 출력",
    "Saída da soundbar": "사운드바 출력",
    "Saída de leitura indisponível; selecione novamente o dispositivo.": "판독 출력을 사용할 수 없습니다. 장치를 다시 선택하세요.",
    "Saída de áudio indisponível. Pedido preservado.": "오디오 출력을 사용할 수 없습니다. 주문이 보존되었습니다.",
    "Saída padrão": "표준 출력",
    "Saída padrão do Windows": "Windows 표준 출력",
    "Saída selecionada indisponível; áudio não enviado à saída padrão.": "선택한 출력을 사용할 수 없습니다. 오디오가 표준 출력으로 전송되지 않았습니다.",
    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "오디오 출력이 업데이트되었습니다. 판독 출력을 선택합니다.",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "독특한 오디오 출력. SR과 Kaia는 서로 다른 장치를 사용합니다. ffmpeg -f wasapi를 사용하지 마십시오(많은 Windows 빌드에는 이 muxer가 없습니다). 기본값 = ffplay. 선택한 장치 = ffmpeg PCM + 사운드 장치.",
    "Scripts": "스크립트",
    "Segredo protegido já salvo; vazio mantém o atual": "보호된 비밀이 이미 저장되었습니다. 비어 있으면 현재 상태로 유지됩니다.",
    "Selecione a URL acima para copiar.": "복사하려면 위의 URL을 선택하세요.",
    "Selecione a saída do leitor: os sons do chat usam essa saída privada.": "리더 출력 선택: 채팅 사운드는 이 비공개 출력을 사용합니다.",
    "Selecione a saída e salve antes de ativar.": "출력을 선택하고 활성화하기 전에 저장하십시오.",
    "Selecione e salve a saída de áudio do Leitor primeiro.": "먼저 리더의 오디오 출력을 선택하고 저장하세요.",
    "Selecione e salve a saída de áudio primeiro.": "먼저 오디오 출력을 선택하고 저장하세요.",
    "Selecione e salve a saída do Leitor.": "Reader 출력을 선택하고 저장합니다.",
    "Seletor CSS do texto": "텍스트 CSS 선택기",
    "Seletor do texto do alerta": "경고 텍스트 선택기",
    "Seletores: #box, #lab, #tit, #who, .bar, #fill, #tempo. Não altera áudio ou reprodução.": "선택기: #box, #lab, #tit, #who, .bar, #fill, #tempo. 오디오나 재생을 변경하지 않습니다.",
    "Seletores: #feed, .message, .user, .message-text, .platform e [data-platform=\"kick\"]. O tempo das mensagens segue a aba Chat. O CSS é aplicado ao salvar.": "선택기: #feed, .message, .user, .message-text, .platform 및 [data-platform=\"kick\"]. 메시지 타이밍은 채팅 탭을 따릅니다. 저장 시 CSS가 적용됩니다.",
    "Sem login • Emotes nativos + 7TV, BTTV e FFZ públicos": "로그인 없음 • 기본 감정 표현 + 공개 7TV, BTTV 및 FFZ",
