    "Teste da saída de leitura do chat.": "채팅 읽기 출력을 테스트 중입니다.",
    "Teste visual": "시각적 테스트",
    "Texto": "텍스트",
    "Thalita · português BR": "탈리타 · 포르투갈어 BR",
    "Todas as plataformas": "모든 플랫폼",
    "Todas as vozes": "모든 목소리",
    "Todos os idiomas": "모든 언어",
    "Tom de teste enviado à saída do SR. Confirme se você ouviu; este teste não usa YouTube nem os alertas.": "테스트 톤이 SR 출력으로 전송됩니다. 들었음을 확인하세요. 이 테스트는 YouTube나 알림을 사용하지 않습니다.",
    "Toque uma música no Spotify. A faixa aparecerá aqui e nos HUDs. Não envie suas chaves ou tokens ao GitHub.": "Spotify에서 노래를 재생해 보세요. 배너는 여기와 HUD에 나타납니다. 키나 토큰을 GitHub에 제출하지 마세요.",
    "Transcrição do chat": "채팅 내용",
    "Twitch e Kick no mesmo painel 💜": "Twitch와 Kick이 같은 패널에 있습니다 💜",
    "Twitch recusou leitura sem login": "Twitch는 로그인 없이 읽기를 거부했습니다.",
    "Twitch — aguardando": "트위치 - 기다리고 있어요",
    "Título (px)": "제목(px)",
    "URL copiada.": "URL이 복사되었습니다.",
    "URL copiada. No OBS, use Fonte de navegador e fundo transparente.": "URL이 복사되었습니다. OBS에서는 브라우저 글꼴과 투명한 배경을 사용합니다.",
    "URL da API JSON": "JSON API URL",
