    "URL do widget": "위젯 URL",
    "URL privado do widget de alertas": "알림 위젯 비공개 URL",
    "Um nick por linha": "한 줄에 하나의 닉네임",
    "Um nick por linha, ou separe por vírgulas. Aceita @ e ignora maiúsculas/minúsculas. O bloqueio é apenas neste overlay.": "닉네임은 한 줄에 하나씩 입력하거나 쉼표로 구분하세요. @를 허용하고 대소문자를 무시합니다. 차단은 이 오버레이에서만 가능합니다.",
    "Uma entrada por dispositivo físico. Prefere WASAPI do PortAudio.": "물리적 장치당 하나의 항목입니다. PortAudio의 WASAPI를 선호하세요.",
    "Uma playlist já está sendo importada. Aguarde o resultado na tela.": "재생목록을 이미 가져오는 중입니다. 화면에 결과가 나올 때까지 기다리세요.",
    "Usar este TXT": "이 TXT를 사용하세요",
    "Use URL HTTP/HTTPS do widget, sem senha no endereço.": "주소에 비밀번호를 포함하지 않고 위젯의 HTTP/HTTPS URL을 사용하세요.",
    "Use até 1.000 nicks por lista de bloqueio.": "차단 목록당 최대 1,000개의 닉네임을 사용할 수 있습니다.",
    "Use até 20 fontes de alertas.": "최대 20개의 경고 소스를 사용합니다.",
    "Use campos JSON separados por ponto, sem código.": "코드 없이 점으로 구분된 JSON 필드를 사용하세요.",
    "Use um endpoint JSON público. Links de live e widgets HTML não são lidos automaticamente; cada serviço precisa permitir acesso às mensagens.": "공개 JSON 엔드포인트를 사용하세요. 라이브 링크와 HTML 위젯은 자동으로 읽혀지지 않습니다. 각 서비스는 메시지에 대한 액세스를 허용해야 합니다.",
    "Use uma API HTTPS pública ou HTTP local, sem senha na URL.": "URL에 비밀번호 없이 공개 HTTPS 또는 로컬 HTTP API를 사용하세요.",
    "Use ↑/↓ ou informe a posição para organizar manualmente. A ordem de cada lista é independente; ordenar desativa o aleatório.": "↑/↓를 이용하거나 위치를 입력하여 수동으로 정리하세요. 각 목록의 순서는 독립적입니다. 순서는 무작위를 비활성화합니다.",
    "Velocidade (%)": "속도(%)",
    "Vertical": "수직",
    "Volume": "볼륨",
    "Volume (%)": "음량 (%)",
    "Voz": "음성",
    "Vídeo privado, removido ou indisponível; escolha outra faixa.": "동영상이 비공개이거나 삭제되었거나 사용할 수 없습니다. 다른 트랙을 선택하세요.",
    "Vídeo: Redirect URI": "비디오: 리디렉션 URI",
    "Vídeo: obter Client ID": "비디오: 클라이언트 ID 받기",
    "Vídeos complementares em inglês podem mostrar uma interface antiga. Para a URL e o fluxo atuais, siga este tutorial e o guia oficial.": "영어로 된 보충 비디오에는 이전 인터페이스가 표시될 수 있습니다. 현재 URL과 흐름을 보려면 이 튜토리얼과 공식 가이드를 따르세요.",
    "Widget": "위젯",
    "Widget para sua live": "라이브를 위한 위젯",
    "Widget salvo. Prévia e OBS atualizados.": "위젯이 저장되었습니다. 미리보기 및 OBS가 업데이트되었습니다.",
    "YouTube acessível; áudio resolvido sem reproduzir.": "접근 가능한 YouTube; 오디오가 재생되지 않고 해결되었습니다.",
    "YouTube exige login para este acesso. Na aba SR, clique Conectar YouTube, faça login na sessão dedicada e depois Testar acesso.": "YouTube에 액세스하려면 로그인이 필요합니다. SR 탭에서 Connect YouTube를 클릭하고 전용 세션에 로그인한 후 테스트 액세스를 클릭하세요.",
    "YouTube limitou as requisições (HTTP 429). SR aguardando 10 minutos antes de tentar novamente.": "YouTube 제한 요청(HTTP 429) SR은 10분 후에 다시 시도합니다.",
    "[histórico]": "[역사]",
    "[spotify HUD]": "[스포티파이 HUD]",
    "\\b(?:coloca|p[oõ]e|bota)\\s+(.+?)\\s+(?:pra|para)\\s+tocar\\b": "\\b(?:put|p[oõ]e|boot)\\s+(.+?)\\s+(?:pra|para)\\s+play\\b",
    "\\b(?:toca|toque|tocar|play|reproduz(?:e|ir)?)\\b(?:\\s+(?:pra|para)\\s+mim)?(?:\\s+(?:a|o|uma|um))?(?:\\s+(?:m[uú]sica|musica|som|faixa|track|song))?(?:\\s+(?:do|da|de|o|a))?\\s*(.+)$": "\\b(?:play|tap|touch|play|play(?:e|go)?)\\b(?:\\s+(?:for|to)\\s+me)?(?:\\s+(?:a|o|um a|um))?(?:\\s+(?:m[uú]sica|musica|sound|track|track|song))?(?:\\s+(?:do|da|de|o|a))?\\s*(.+)$",
    "\\s*\\((wasapi|mme|directsound|windows ds|wdm[- ]?ks|primary sound driver)[^)]*\\)": "\\s*\\((wasapi|mme|directsound|windows ds|wdm[- ]?ks|기본 사운드 드라이버)[^)]*\\)",
    "\\s*\\(\\d+\\s*[-–]\\s*(in|out|entrada|saída|saida)[^)]*\\)": "\\s*\\(\\d+\\s*[-–]\\s*(in|out|in|out|out)[^)]*\\)",
    "^(a|o|uma|um|m[uú]sica|musica|som)\\s+": "^(a|a|a|m[uús]sica|musica|sound)\\s+",
    "^(kaia|caia|caio|kaiá|caiá)[,:\\s]+": "^(kaia|caia|caio|kaiá|caiá)[,:\\s]+",
