    "; tentando novamente…": ";再试一次...",
    "<img alt=\"\" src=\"assets/flags/": "<img alt=\"\" src=\"资产/标志/",
    "=== Kaia Chat — sessão {0} ===": "=== Kaia 聊天 — 会话 {0} ===",
    "A API precisa fornecer um ID único para cada mensagem.": "API 需要为每条消息提供唯一的 ID。",
    "A API retornou uma resposta muito grande.": "API 返回了非常大的响应。",
    "A porta 19348 está ocupada. Feche outra autorização Spotify e tente novamente.": "19348 端口正忙。关闭另一个 Spotify 授权并重试。",
    "A prévia usa a música real. Somente Salvar aplica as alterações à fonte do OBS.": "预览使用实际音乐。仅“保存”会将更改应用到 OBS 源。",
    "A sessão YouTube demorou para responder.": "YouTube 会话响应缓慢。",
    "API personalizada HTTP {0}": "自定义 HTTP API {0}",
    "Abra a sessão dedicada do SR no Chrome/Edge e faça login no YouTube se necessário. A sessão é reutilizada e sincronizada automaticamente. Não é preciso procurar cookies ou cache em pastas. Restrições do YouTube podem exigir nova autenticação ou impedir algumas faixas.": "在 Chrome/Edge 中打开专用 SR 会话，并在必要时登录 YouTube。会话会自动重用和同步。无需在文件夹中搜索 cookie 或缓存。 YouTube 限制可能需要重新验证或阻止某些曲目。",
    "Abra o Spotify Developer Dashboard e entre com sua conta. Aplicações em Development Mode exigem Premium do proprietário e usuários autorizados no painel.": "打开 Spotify 开发者仪表板并使用您的帐户登录。开发模式下的应用程序需要面板中所有者和授权用户的高级版。",
    "Abre o player com nome próprio: kaia_sr.exe ou kaia_voz.exe.": "使用自己的名称打开播放器：kaia_sr.exe 或 kaia_voz.exe。",
    "Abrir HUD original": "打开原版HUD",
    "Abrir HUD padrão": "打开默认HUD",
    "Abrir HUD personalizado": "打开自定义 HUD",
    "Abrir configurações / liberar cliques": "打开设置/释放点击",
