    "Abrir prévia desta fonte": "打开此字体的预览",
    "Aceitar pedidos !sr das lives": "接受订单！sr das live",
    "Acha o vídeo mais próximo do nome. Link = usa o id. Nome = busca ytsearch.": "找到最接近该名称的视频。链接 = 使用 id。名称 = ytsearch 搜索。",
    "Adicionar faixa à playlist de fundo": "将曲目添加到后台播放列表",
    "Adicionar pedido SR": "添加SR订单",
    "Adicionar playlist": "添加播放列表",
    "Adicione a URL como Fonte de navegador no OBS. Mantenha o Kaia Chat aberto, mesmo com a janela oculta.": "将 URL 添加为 OBS 中的浏览器源。即使窗口隐藏，也保持 Kaia Chat 处于打开状态。",
    "Adicione os URLs de widget usados no OBS. Streamlabs, StreamElements ou serviço personalizado. Cada fonte tem seu próprio nome/plataforma. Os widgets ficam sem som; o texto reconhecido é lido somente na saída do Leitor. Ativar fontes de alerta também permite avisos com a leitura normal desligada.": "添加OBS中使用的小组件URL。 Streamlabs、StreamElements 或定制服务。每种字体都有自己的名称/平台。小部件已静音；识别的文本在 Reader 输出处是只读的。启用警报源还可以在关闭正常读数的情况下启用警告。",
    "Aguardando pedido !sr": "等待订单！sr",
    "Alertas": "提醒",
    "Alertas para o streamer": "流光警报",
    "Alguns áudios temporários estão em uso. A limpeza será repetida na próxima abertura.": "正在使用一些临时音频。下次开放时将重复清洁。",
    "Alguém": "有人",
    "Alt": "替代",
    "Alta prioridade": "高优先级",
    "Alta prioridade lê todas as mensagens e passa à frente da fila, após terminar a fala atual. Prioridade normal e baixa têm contagens separadas. Para acompanhar a live, mensagens antigas são descartadas conforme o atraso máximo, inclusive as prioritárias. Em fila cheia, as mais antigas de menor prioridade saem primeiro. O intervalo conta desde o início da preparação, sem acrescentar uma pausa após cada fala. Histórico recuperado ao conectar não é falado.": "高优先级读取所有消息，并在完成当前语音后移动到队列的前面。正常和低优先级具有单独的计数。为了跟直播，旧消息会根据最大延迟被丢弃，包括优先级消息。在满队列中，优先级最低的最旧的队列首先离开。休息时间从准备开始算起，每次发言后不加停顿。连接时检索到的历史记录不会被说出。",
