    "Não foi possível salvar. Reabra a Kaia para carregar o servidor do editor.": "无法保存。重新打开 Kaia 以加载发布者服务器。",
    "Não foi possível salvar:": "无法保存：",
    "Não foi possível tocar o som. Escolha e salve a saída do leitor na aba Leitor.": "无法播放声音。在“阅读器”选项卡中选择并保存阅读器输出。",
    "Não li a playlist:": "我没有阅读播放列表：",
    "Não li a playlist: {0}": "我没有阅读播放列表：{0}",
    "O SR está no mudo, independentemente do volume salvo.": "无论保存的音量如何，SR 都会静音。",
    "O Spotify publica a faixa nos HUDs; a reprodução continua no aplicativo Spotify. A autorização e os tokens são renovados automaticamente. O SR reproduz pedidos do YouTube, não baixa áudio do Spotify.": "Spotify 将曲目发布到 HUD； Spotify 应用程序中继续播放。授权和令牌会自动更新。 SR 播放来自 YouTube 的请求，不从 Spotify 下载音频。",
    "O backup inclui mensagens recebidas de todas as plataformas, inclusive os nicks ocultos por Chats bloqueados. O fade só limpa a tela.": "备份包括从所有平台收到的消息，包括被阻止的聊天隐藏的昵称。淡入淡出只会清除屏幕。",
    "O campo da lista de mensagens não contém um array JSON.": "消息列表字段不包含 JSON 数组。",
    "O comando {0} demorou demais. Os outros controles continuam disponíveis; tente novamente.": "{0} 命令花费的时间太长。其他控件仍然可用；再试一次。",
    "O decodificador não produziu áudio.": "解码器没有产生音频。",
    "O medidor usa o áudio da saída selecionada. Outros sons no mesmo dispositivo também podem aparecer. O editor preserva temas, CSS, RGB e barras do pacote original.": "仪表使用来自所选输出的音频。同一设备上的其他声音也可能会出现。编辑器保留原始包中的主题、CSS、RGB 和栏。",
    "O motor de áudio demorou para iniciar.": "音频引擎启动缓慢。",
    "O navegador não liberou a sessão dedicada. Feche essa janela do YouTube e tente Conectar novamente.": "浏览器没有释放专用会话。关闭此 YouTube 窗口并再次尝试连接。",
    "O navegador recusou a sincronização da sessão.": "浏览器拒绝同步会话。",
    "O segundo overlay mostra os mesmos dados do SR/Spotify. Edite a aparência aqui; o HUD padrão continua disponível.": "第二个叠加层显示与 SR/Spotify 相同的数据。在这里编辑外观；标准 HUD 仍然可用。",
    "OBS → adicionar Fonte de navegador. Use inicialmente 800 × 320 e recorte conforme o layout. Fundo transparente; não precisa chroma key.": "注意 → 添加浏览器字体。最初使用800×320并根据布局进行裁剪。透明背景；不需要色度键。",
    "Oculte mensagens e sons de nicks específicos": "隐藏特定昵称的消息和声音",
    "Opacidade do fundo (%)": "背景不透明度 (%)",
