    "Padrão do Windows": "Windows 标准版",
    "Para ouvir só no headset, escolha uma saída que não esteja capturada no OBS. A leitura não troca para a saída padrão se o dispositivo escolhido ficar indisponível. Voz Edge requer internet.": "要仅在耳机上收听，请选择 OBS 中未捕获的输出。如果所选设备不可用，则读取不会切换到标准输出。 Edge Voice 需要互联网。",
