    "Pedidos !sr ativos.": "活跃 !sr 订单。",
    "Pedidos !sr nome da música ou !sr link do YouTube, recebidos nos chats conectados, entram na fila. Ative abaixo para aceitar pedidos. Usuários bloqueados e mensagens históricas são ignorados.": "在连接的聊天中收到的对 !sr 歌曲名称或 !sr YouTube 链接的请求进入队列。激活下方以接受订单。被阻止的用户和历史消息将被忽略。",
