    "Preservar as cores dos nomes de usuário": "保留用户名颜色",
    "Privacidade dos áudios: músicas do SR são transmitidas sem download permanente. As falas usam arquivos temporários, apagados após o uso e ao fechar. Restos de uma interrupção são limpos na próxima inicialização do motor de áudio. Sons escolhidos por você e o backup TXT são preservados.": "音频隐私：SR 歌曲无需永久下载即可传输。演讲使用临时文件，在使用后和关闭时删除。中断的残留物将在下一次音频引擎启动时清除。您选择的声音和 TXT 备份将被保留。",
    "Proteção de credenciais indisponível neste Windows.": "凭据保护在此 Windows 上不可用。",
