    "Salve e ative a fonte antes de abrir a prévia.": "在打开预览之前保存并激活字体。",
    "Salve no botão Salvar SR. Pedidos são os próximos a tocar depois da faixa atual, antes das músicas da playlist. Os limites valem para novas entradas e não removem músicas já aceitas. Sons do chat e avisos usam a saída do Leitor; música usa a saída do SR. O OBS deve capturar só a saída/processo do SR para manter os avisos privados.": "使用保存 SR 按钮保存。请求在当前曲目之后、播放列表中的歌曲之前播放。这些限制适用于新条目，并且不会删除已接受的歌曲。聊天声音和提示使用 Reader 输出；音乐使用SR输出。 OBS 应仅捕获 SR 输出/进程以保持警告的私密性。",
    "Salve seu Client ID primeiro.": "首先保存您的客户 ID。",
    "Salvo. O overlay do OBS atualiza em até dois segundos.": "已保存。 OBS 叠加层会在两秒内更新。",
    "Saída SR indisponível. Selecione novamente a saída da música.": "SR 输出不可用。再次选择音乐输出。",
    "Saída da leitura": "读取输出",
