    "Saída da soundbar": "条形音箱输出",
    "Saída de leitura indisponível; selecione novamente o dispositivo.": "无法读取输出；再次选择设备。",
    "Saída de áudio indisponível. Pedido preservado.": "音频输出不可用。订单已保留。",
    "Saída padrão": "标准输出",
    "Saída padrão do Windows": "Windows 标准输出",
    "Saída selecionada indisponível; áudio não enviado à saída padrão.": "所选输出不可用；音频未发送到标准输出。",
    "Saídas de áudio atualizadas. Selecione a saída da leitura.": "更新了音频输出。选择读数输出。",
    "Saídas de áudio únicas. SR e Kaia usam dispositivos diferentes. Não usa ffmpeg -f wasapi (muita build do Windows não tem esse muxer). Padrão = ffplay. Dispositivo escolhido = ffmpeg PCM + sounddevice.": "独特的音频输出。 SR 和 Kaia 使用不同的设备。不要使用 ffmpeg -f wasapi （许多 Windows 版本没有此复用器）。默认 = ffplay。选择的设备 = ffmpeg PCM + sounddevice。",
    "Scripts": "脚本",
    "Segredo protegido já salvo; vazio mantém o atual": "受保护的秘密已保存；空保持当前状态",
