    "Seletor do texto do alerta": "警报文本选择器",
    "Seletores: #box, #lab, #tit, #who, .bar, #fill, #tempo. Não altera áudio ou reprodução.": "选择器：#box、#lab、#tit、#who、.bar、#fill、#tempo。不更改音频或播放。",
    "Seletores: #feed, .message, .user, .message-text, .platform e [data-platform=\"kick\"]. O tempo das mensagens segue a aba Chat. O CSS é aplicado ao salvar.": "选择器：#feed、.message、.user、.message-text、.platform 和 [data-platform=\"kick\"]。消息的发送时间遵循“聊天”选项卡。 CSS 在保存时应用。",
